{"command":"cat > src/pipr_config.rs <<'RS'
use anyhow::{anyhow, Result};
use std::collections::HashMap;
use std::fs;
use std::path::{Component, Path, PathBuf};

pub const DEFAULT_CONFIG: &str = r#"
#  ____  _
# |  _ \(_)_ __  _ __       .________.
# | |_) | | '_ \| '__|      |________|
# |  __/| | |_) | |          |_    -|
# |_|   |_| .__/|_|     xX  xXx___x_|
#         |_|
#
# A commandline utility by
# Leon Kowarschick

# finish_hook: Executed once you close pipr, getting the command you constructed piped into stdin.
# finish_hook = "xclip -selection clipboard -in"

# Paranoid history mode writes every sucessfully running command into the history in autoeval mode.
paranoid_history_mode_default = false

autoeval_mode_default = true

history_size = 500
cmdlist_always_show_preview = false
cmd_timeout_millis = 2000

highlighting_enabled = true

eval_environment = ["bash", "-c"]

# Snippets can be used to quickly insert common bits of shell
# use || (two pipes) where you want your cursor to be after insertion
[snippets]
s = " | sed -r 's/||//g'"

[help_viewers]
'm' = "man ??"
'h' = "?? --help | less"

[output_viewers]
'l' = "less"
"#;

#[derive(Debug, Clone)]
pub struct PiprConfig {
    pub finish_hook: Option<String>,
    pub paranoid_history_mode_default: bool,
    pub autoeval_mode_default: bool,
    pub history_size: usize,
    pub cmdlist_always_show_preview: bool,
    pub cmd_timeout_millis: u64,
    pub highlighting_enabled: bool,
    pub eval_environment: Vec<String>,
    pub snippets: HashMap<char, String>,
    pub help_viewers: HashMap<char, String>,
    pub output_viewers: HashMap<char, String>,
}

fn relative_display(path: &Path) -> String {
    if !path.is_absolute() {
        return path.display().to_string();
    }
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("/"));
    let cwd_parts: Vec<String> = cwd
        .components()
        .filter_map(|c| match c {
            Component::Normal(s) => Some(s.to_string_lossy().into_owned()),
            _ => None,
        })
        .collect();
    let path_parts: Vec<String> = path
        .components()
        .filter_map(|c| match c {
            Component::Normal(s) => Some(s.to_string_lossy().into_owned()),
            _ => None,
        })
        .collect();
    let mut common = 0;
    while common < cwd_parts.len()
        && common < path_parts.len()
        && cwd_parts[common] == path_parts[common]
    {
        common += 1;
    }
    let mut out = String::new();
    for _ in common..cwd_parts.len() {
        if !out.is_empty() {
            out.push('/');
        }
        out.push_str("..");
    }
    for part in &path_parts[common..] {
        if !out.is_empty() {
            out.push('/');
        }
        out.push_str(part);
    }
    if out.is_empty() {
        out.push('.');
    }
    out
}

fn scalar_to_string(value: &toml::Value) -> Option<String> {
    match value {
        toml::Value::String(s) => Some(s.clone()),
        toml::Value::Integer(i) => Some(i.to_string()),
        toml::Value::Float(f) => Some(f.to_string()),
        toml::Value::Boolean(b) => Some(b.to_string()),
        toml::Value::Datetime(d) => Some(d.to_string()),
        _ => None,
    }
}

fn get_bool(table: &toml::Table, key: &str, default: bool) -> bool {
    match table.get(key) {
        Some(toml::Value::Boolean(b)) => *b,
        Some(toml::Value::Integer(i)) => *i != 0,
        Some(toml::Value::Float(f)) => *f != 0.0,
        Some(toml::Value::String(s)) => match s.to_ascii_lowercase().as_str() {
            "true" | "on" | "yes" | "1" => true,
            "false" | "off" | "no" | "0" => false,
            _ => default,
        },
        _ => default,
    }
}

fn get_int(table: &toml::Table, key: &str, default: i64) -> i64 {
    match table.get(key) {
        Some(toml::Value::Boolean(b)) => {
            if *b {
                1
            } else {
                0
            }
        }
        Some(toml::Value::Integer(i)) => *i,
        Some(toml::Value::Float(f)) => f.round() as i64,
        Some(toml::Value::String(s)) => s.parse::<i64>().unwrap_or(default),
        _ => default,
    }
}

fn get_map(table: &toml::Table, key: &str) -> HashMap<char, String> {
    let mut result = HashMap::new();
    if let Some(toml::Value::Table(map)) = table.get(key) {
        for (k, v) in map {
            let mut chars = k.chars();
            let (Some(ch), None) = (chars.next(), chars.next()) else {
                return HashMap::new();
            };
            let Some(value) = scalar_to_string(v) else {
                return HashMap::new();
            };
            result.insert(ch, value);
        }
    }
    result
}

impl PiprConfig {
    pub fn load(path: &Path) -> Result<Self> {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).unwrap();
        }
        if !path.exists() {
            fs::write(path, DEFAULT_CONFIG).unwrap();
        }
        if !path.is_file() {
            return Err(anyhow!("configuration file {:?} not found", path));
        }
        let content = fs::read_to_string(path)?;
        let table: toml::Table = toml::from_str(&content).map_err(|e| {
            anyhow!("{} in {}", e, relative_display(path))
        })?;

        let eval_environment = match table.get("eval_environment") {
            Some(toml::Value::Array(items)) => items.iter().filter_map(scalar_to_string).collect(),
            _ => vec!["bash".to_string(), "-c".to_string()],
        };

        Ok(Self {
            finish_hook: table.get("finish_hook").and_then(scalar_to_string),
            paranoid_history_mode_default: get_bool(
                &table,
                "paranoid_history_mode_default",
                false,
            ),
            autoeval_mode_default: get_bool(&table, "autoeval_mode_default", false),
            history_size: get_int(&table, "history_size", 500) as usize,
            cmdlist_always_show_preview: get_bool(
                &table,
                "cmdlist_always_show_preview",
                false,
            ),
            cmd_timeout_millis: get_int(&table, "cmd_timeout_millis", 2000) as u64,
            highlighting_enabled: get_bool(&table, "highlighting_enabled", true),
            eval_environment,
            snippets: get_map(&table, "snippets"),
            help_viewers: get_map(&table, "help_viewers"),
            output_viewers: get_map(&table, "output_viewers"),
        })
    }
}
RS"}

