use std::fs;
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct CommandList {
    pub entries: Vec<String>,
    file_path: Option<PathBuf>,
    max_size: Option<usize>,
}

impl CommandList {
    pub fn load(file_path: PathBuf, max_size: Option<usize>) -> Self {
        let mut list = Self {
            entries: Vec::new(),
            file_path: Some(file_path.clone()),
            max_size,
        };
        let content = fs::read_to_string(&file_path).unwrap_or_default();
        let mut current: Vec<String> = Vec::new();
        for line in content.lines() {
            if line.is_empty() {
                continue;
            }
            if line == "---" {
                list.add(&current.join("\n"));
                current.clear();
            } else {
                current.push(line.to_string());
            }
        }
        list.add(&current.join("\n"));
        list
    }

    pub fn new_temporary(entries: Vec<String>) -> Self {
        Self {
            entries,
            file_path: None,
            max_size: None,
        }
    }

    pub fn add(&mut self, entry: &str) {
        if entry.is_empty() {
            return;
        }
        if self.entries.last().map(|s| s.as_str()) == Some(entry) {
            return;
        }
        self.entries.push(entry.to_string());
        if let Some(max) = self.max_size {
            if self.entries.len() > max {
                let excess = self.entries.len() - max;
                self.entries.drain(0..excess);
            }
        }
        self.save();
    }

    pub fn save(&self) {
        if let Some(path) = &self.file_path {
            fs::write(path, self.entries.join("\n---\n")).unwrap();
        }
    }

    pub fn set_entries_and_save(&mut self, entries: Vec<String>) {
        self.entries = entries;
        self.save();
    }

    pub fn remove_first(&mut self, entry: &str) -> bool {
        if let Some(pos) = self.entries.iter().position(|e| e == entry) {
            self.entries.remove(pos);
            self.save();
            true
        } else {
            false
        }
    }
}
