#[derive(Debug, Clone)]
pub struct TextField {
    pub lines: Vec<String>,
    pub cursor_x: usize,
    pub cursor_y: usize,
}

fn char_to_byte(s: &str, char_idx: usize) -> usize {
    s.char_indices()
        .nth(char_idx)
        .map(|(idx, _)| idx)
        .unwrap_or_else(|| s.len())
}

impl Default for TextField {
    fn default() -> Self {
        Self {
            lines: vec![String::new()],
            cursor_x: 0,
            cursor_y: 0,
        }
    }
}

impl TextField {
    pub fn set_content(&mut self, content: &str) {
        self.lines = content.lines().map(|s| s.to_string()).collect();
        if self.lines.is_empty() {
            self.lines.push(String::new());
        }
        self.cursor_y = self.lines.len() - 1;
        self.cursor_x = self.lines[self.cursor_y].chars().count();
    }

    pub fn get_content(&self) -> String {
        self.lines.join("\n")
    }

    fn current_line_len(&self) -> usize {
        self.lines[self.cursor_y].chars().count()
    }

    pub fn insert_char(&mut self, c: char) {
        let byte_idx = char_to_byte(&self.lines[self.cursor_y], self.cursor_x);
        self.lines[self.cursor_y].insert(byte_idx, c);
        self.cursor_x += 1;
    }

    pub fn insert_snippet(&mut self, snippet: &str) {
        let placeholder_pos = snippet
            .find("||")
            .map(|byte_idx| snippet[..byte_idx].chars().count());
        let cleansed = snippet.replace("||", "");
        let byte_idx = char_to_byte(&self.lines[self.cursor_y], self.cursor_x);
        self.lines[self.cursor_y].insert_str(byte_idx, &cleansed);
        self.cursor_x += placeholder_pos.unwrap_or_else(|| cleansed.chars().count());
    }

    pub fn insert_newline(&mut self) {
        let byte_idx = char_to_byte(&self.lines[self.cursor_y], self.cursor_x);
        let after = self.lines[self.cursor_y][byte_idx..].to_string();
        self.lines[self.cursor_y].truncate(byte_idx);
        self.cursor_y += 1;
        self.cursor_x = 0;
        self.lines.insert(self.cursor_y, after);
    }

    pub fn backspace(&mut self) {
        if self.cursor_x > 0 {
            let byte_idx = char_to_byte(&self.lines[self.cursor_y], self.cursor_x - 1);
            self.lines[self.cursor_y].remove(byte_idx);
            self.cursor_x -= 1;
        } else if self.cursor_y > 0 {
            let current = self.lines.remove(self.cursor_y);
            self.cursor_y -= 1;
            self.cursor_x = self.current_line_len();
            self.lines[self.cursor_y].push_str(&current);
        }
    }

    pub fn delete(&mut self) {
        if self.cursor_x < self.current_line_len() {
            let byte_idx = char_to_byte(&self.lines[self.cursor_y], self.cursor_x);
            self.lines[self.cursor_y].remove(byte_idx);
        } else if self.cursor_y + 1 < self.lines.len() {
            let next = self.lines.remove(self.cursor_y + 1);
            self.lines[self.cursor_y].push_str(&next);
        }
    }

    pub fn move_left(&mut self) {
        if self.cursor_x > 0 {
            self.cursor_x -= 1;
        } else if self.cursor_y > 0 {
            self.cursor_y -= 1;
            self.cursor_x = self.current_line_len();
        }
    }

    pub fn move_right(&mut self) {
        if self.cursor_x < self.current_line_len() {
            self.cursor_x += 1;
        } else if self.cursor_y + 1 < self.lines.len() {
            self.cursor_y += 1;
            self.cursor_x = 0;
        }
    }

    pub fn move_up(&mut self) {
        if self.cursor_y > 0 {
            self.cursor_y -= 1;
            self.cursor_x = self.cursor_x.min(self.current_line_len());
        }
    }

    pub fn move_down(&mut self) {
        if self.cursor_y + 1 < self.lines.len() {
            self.cursor_y += 1;
            self.cursor_x = self.cursor_x.min(self.current_line_len());
        }
    }

    pub fn home(&mut self) {
        self.cursor_x = 0;
    }

    pub fn end(&mut self) {
        self.cursor_x = self.current_line_len();
    }

    pub fn clear(&mut self) {
        self.lines = vec![String::new()];
        self.cursor_x = 0;
        self.cursor_y = 0;
    }

    pub fn delete_word(&mut self) {
        let separators = [' ', '/', '-', '_', ':', '\\'];
        let chars: Vec<char> = self.lines[self.cursor_y].chars().collect();
        if self.cursor_x == 0 {
            if !chars.is_empty() {
                // This mirrors a boundary case of the utility being recreated.
                self.lines[self.cursor_y].remove(0);
            }
            return;
        }
        let upto = self.cursor_x.min(chars.len());
        let start = chars[..upto]
            .iter()
            .rposition(|c| separators.contains(c))
            .unwrap_or(0);
        let start_byte = char_to_byte(&self.lines[self.cursor_y], start);
        let end_byte = char_to_byte(&self.lines[self.cursor_y], upto);
        self.lines[self.cursor_y].replace_range(start_byte..end_byte, "");
        self.cursor_x = start;
    }

    pub fn absolute_cursor_char(&self) -> usize {
        let mut pos = 0;
        for (idx, line) in self.lines.iter().enumerate() {
            if idx == self.cursor_y {
                pos += self.cursor_x;
                break;
            }
            pos += line.chars().count() + 1;
        }
        pos
    }
}
