pub struct Executor {
    pub pending: Vec<Receiver<EvalResult>>,
    current_child: Option<Arc<Mutex<Child>>>,
    timeout_millis: u64,
    isolation: bool,
    config: PiprConfig,
}

impl Executor {
    pub fn new(config: PiprConfig, isolation: bool) -> Self {
        Self {
            pending: Vec::new(),
            current_child: None,
            timeout_millis: config.cmd_timeout_millis,
            isolation,
            config,
        }
    }

    fn make_result(
        tx: Sender<EvalResult>,
        stdout: String,
        stderr: String,
        success: bool,
        submitted_input: String,
    ) {
        let _ = tx.send(EvalResult {
            stdout,
            stderr,
            success,
            submitted_input,
        });
    }

    pub fn launch(&mut self, submitted_input: String, shell_command: String, stdin_data: String) {
        if let Some(child) = &self.current_child {
            if let Ok(mut child) = child.lock() {
                let _ = child.kill();
            }
        }

        let (tx, rx) = channel::<EvalResult>();
        self.pending.push(rx);

        let Some(mut cmd) = build_command(&self.config, self.isolation, &shell_command) else {
            Self::make_result(
                tx,
                String::new(),
                "shell_command is empty".to_string(),
                false,
                submitted_input,
            );
            return;
        };

        cmd.stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());

        let child = match cmd.spawn() {
            Ok(child) => child,
            Err(_) => {
                Self::make_result(
                    tx,
                    String::new(),
                    "Unable to spawn command".to_string(),
                    false,
                    submitted_input,
                );
                return;
            }
        };

        let mut child = child;
        let mut stdin_handle = child.stdin.take();
        let stdout_handle = child.stdout.take();
        let stderr_handle = child.stderr.take();
        let child = Arc::new(Mutex::new(child));
        self.current_child = Some(child.clone());
        let timeout_millis = self.timeout_millis;

        thread::spawn(move || {
            if let Some(mut stdin) = stdin_handle.take() {
                let _ = stdin.write_all(stdin_data.as_bytes());
                let _ = stdin.flush();
                drop(stdin);
            }

            let start = Instant::now();
            let deadline = start.checked_add(Duration::from_millis(timeout_millis));
            let status;
            loop {
                let result = {
                    let mut guard = match child.lock() {
                        Ok(g) => g,
                        Err(poisoned) => poisoned.into_inner(),
                    };
                    guard.try_wait()
                };
                match result {
                    Ok(Some(s)) => {
                        status = s;
                        break;
                    }
                    Ok(None) => {
                        if let Some(deadline) = deadline {
                            if Instant::now() >= deadline {
                                if let Ok(mut guard) = child.lock() {
                                    let _ = guard.kill();
                                    // Reap the process; ignore its output just
                                    // like a timed-out evaluation does.
                                    let _ = guard.wait();
                                }
                                Self::make_result(
                                    tx,
                                    String::new(),
                                    "Command timed out".to_string(),
                                    false,
                                    submitted_input,
                                );
                                return;
                            }
                        }
                        thread::sleep(Duration::from_millis(2));
                    }
                    Err(_) => {
                        Self::make_result(
                            tx,
                            String::new(),
                            String::new(),
                            false,
                            submitted_input,
                        );
                        return;
                    }
                }
            }

            let stdout = stdout_handle.map(string_from_reader).unwrap_or_default();
            let stderr = stderr_handle.map(string_from_reader).unwrap_or_default();
            Self::make_result(tx, stdout, stderr, status.success(), submitted_input);
        });
    }

    pub fn poll_results(&mut self) -> Vec<EvalResult> {
        let mut results = Vec::new();
        let mut retained = Vec::new();
        for receiver in self.pending.drain(..) {
            match receiver.try_recv() {
                Ok(result) => results.push(result),
                Err(std::sync::mpsc::TryRecvError::Empty) => retained.push(receiver),
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {}
            }
        }
        self.pending = retained;
        results
    }
}
