    style::{Color, Modifier, Style},
    text::{Line, Span, Text},
};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct AnsiState {
    fg: Option<Color>,
    bg: Option<Color>,
    mods: Modifier,
}

impl Default for AnsiState {
    fn default() -> Self {
        Self {
            fg: None,
            bg: None,
            mods: Modifier::empty(),
        }
    }
}

impl AnsiState {
    fn style(self) -> Style {
        let mut style = Style::default();
        if let Some(fg) = self.fg {
            style = style.fg(fg);
        }
        if let Some(bg) = self.bg {
            style = style.bg(bg);
        }
        style = style.add_modifier(self.mods);
        style
    }
    fn reset(&mut self) {
        *self = Self::default();
    }
}

fn apply_sgr(state: &mut AnsiState, params_str: &str) {
    if params_str.contains(':') || params_str.starts_with(';') {
        return;
    }
    let mut params: Vec<i64> = Vec::new();
    if params_str.is_empty() {
        params.push(0);
    } else {
        for part in params_str.split(';') {
            if part.is_empty() {
                continue;
            }
            match part.parse::<i64>() {
                Ok(n) => params.push(n),
                Err(_) => return,
            }
        }
        if params.is_empty() {
            params.push(0);
        }
    }

    let mut i = 0;
    while i < params.len() {
        match params[i] {
            0 => state.reset(),
            1 => state.mods.insert(Modifier::BOLD),
            2 => state.mods.insert(Modifier::DIM),
            3 => state.mods.insert(Modifier::ITALIC),
            4 => state.mods.insert(Modifier::UNDERLINED),
            5 => state.mods.insert(Modifier::SLOW_BLINK),
            6 => state.mods.insert(Modifier::RAPID_BLINK),
            7 => state.mods.insert(Modifier::REVERSED),
            9 => state.mods.insert(Modifier::CROSSED_OUT),
            22 => state.mods.remove(Modifier::BOLD | Modifier::DIM),
            30..=37 => state.fg = Some(Color::Indexed((params[i] - 30) as u8)),
            39 => state.fg = None,
            40..=47 => state.bg = Some(Color::Indexed((params[i] - 40) as u8)),
            49 => state.bg = None,
            90..=97 => state.fg = Some(Color::Indexed((8 + params[i] - 90) as u8)),
            100..=107 => state.bg = Some(Color::Indexed((8 + params[i] - 100) as u8)),
            38 | 48 => {
                let is_fg = params[i] == 38;
                if i + 1 >= params.len() {
                    return;
                }
                match params[i + 1] {
                    5 => {
                        if i + 2 >= params.len() || !(0..=255).contains(&params[i + 2]) {
                            return;
                        }
                        let c = Color::Indexed(params[i + 2] as u8);
                        if is_fg {
                            state.fg = Some(c);
                        } else {
                            state.bg = Some(c);
                        }
                        i += 2;
                    }
                    2 => {
                        if i + 4 >= params.len()
                            || !(0..=255).contains(&params[i + 2])
                            || !(0..=255).contains(&params[i + 3])
                            || !(0..=255).contains(&params[i + 4])
                        {
                            return;
                        }
                        let c = Color::Rgb(
                            params[i + 2] as u8,
                            params[i + 3] as u8,
                            params[i + 4] as u8,
                        );
                        if is_fg {
                            state.fg = Some(c);
                        } else {
                            state.bg = Some(c);
                        }
                        i += 4;
                    }
                    _ => return,
                }
            }
            _ => {}
        }
        i += 1;
    }
}

pub fn ansi_to_text(input: &str) -> Text<'static> {
    let mut state = AnsiState::default();
    let mut lines: Vec<Line<'static>> = Vec::new();

    for line_str in input.split('\n') {
        let mut spans: Vec<Span<'static>> = Vec::new();
        let bytes = line_str.as_bytes();
        let mut idx = 0;
        let mut current = String::new();
        let mut current_state = state;

        let flush = |spans: &mut Vec<Span<'static>>, current: &mut String, st: AnsiState| {
            if !current.is_empty() {
                spans.push(Span::styled(std::mem::take(current), st.style()));
            }
        };

        while idx < bytes.len() {
            if bytes[idx] == 0x1b {
                if idx + 1 < bytes.len() && bytes[idx + 1] == b'[' {
                    let mut j = idx + 2;
                    while j < bytes.len() && (0x20..=0x3f).contains(&bytes[j]) {
                        j += 1;
                    }
                    if j < bytes.len() && (0x40..=0x7e).contains(&bytes[j]) {
                        if bytes[j] == b'm' {
                            flush(&mut spans, &mut current, current_state);
                            let params = &line_str[idx + 2..j];
                            apply_sgr(&mut state, params);
                            current_state = state;
                        }
                        idx = j + 1;
                    } else {
                        // Incomplete sequence at the end of this line.
                        idx = bytes.len();
                    }
                    continue;
                } else if idx + 1 < bytes.len() && bytes[idx + 1] == b']' {
                    let mut j = idx + 2;
                    let mut terminated = false;
                    while j < bytes.len() {
                        if bytes[j] == 0x07 {
                            j += 1;
                            terminated = true;
                            break;
                        }
                        if bytes[j] == 0x1b && j + 1 < bytes.len() && bytes[j + 1] == b'\\' {
                            j += 2;
                            terminated = true;
                            break;
                        }
                        j += 1;
                    }
                    idx = if terminated { j } else { bytes.len() };
                    continue;
                } else {
                    // A lone escape is dropped; following bytes are literal.
                    idx += 1;
                    continue;
                }
            }

            // Append one UTF-8 character.
            let ch_len = match std::str::from_utf8(&bytes[idx..]) {
                Ok(s) => s.chars().next().map(|c| c.len_utf8()).unwrap_or(1),
                Err(e) => {
                    let valid = e.valid_up_to();
                    if valid > 0 {
                        valid
                    } else {
                        1
                    }
                }
            };
            let end = (idx + ch_len).min(bytes.len());
            current.push_str(&line_str[idx..end]);
            idx = end;
        }
        flush(&mut spans, &mut current, current_state);
        lines.push(Line::from(spans));
    }

    if lines.is_empty() {
        lines.push(Line::from(""));
    }
    Text::from(lines)
}
RS"}

