    Default,
    Command,
    Builtin,
    Keyword,
    Var,
    Str,
    Number,
    Comment,
}

impl Ink {
    fn color(self) -> Color {
        match self {
            Ink::Default => Color::Rgb(192, 197, 206),
            Ink::Command => Color::Rgb(143, 161, 179),
            Ink::Builtin => Color::Rgb(150, 181, 180),
            Ink::Keyword => Color::Rgb(180, 142, 173),
            Ink::Var => Color::Rgb(191, 97, 106),
            Ink::Str => Color::Rgb(163, 190, 140),
            Ink::Number => Color::Rgb(208, 135, 112),
            Ink::Comment => Color::Rgb(101, 115, 126),
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct SrcChar {
    ch: char,
    line: Option<usize>,
}

