            heredoc_queue: Vec::new(),
            for_stage: 0,
            case_stage: 0,
            in_case_pattern: false,
            in_array: false,
            expect_fd_target: false,
            paren_depth: 0,
        }
    }
}

const BUILTINS: &[&str] = &[
    "bg", "bind", "builtin", "caller", "cd", "command", "disown", "echo", "enable", "eval",
    "exec", "exit", "fg", "getopts", "hash", "help", "jobs", "kill", "let", "logout", "mapfile",
    "printf", "pwd", "read", "readarray", "set", "shift", "shopt", "source", "suspend", "times",
    "trap", "type", "ulimit", "umask", "unalias", "unset", "wait", ".", ":",
];

struct Highlighter {
    src: Vec<SrcChar>,
    colors: Vec<Ink>,
    pos: usize,
}

impl Highlighter {
    fn new(lines: &[String]) -> Self {
        let mut src = Vec::new();
        for (idx, line) in lines.iter().enumerate() {
            if idx > 0 {
                src.push(SrcChar {
                    ch: '\n',
                    line: None,
                });
            }
            for ch in line.chars() {
                src.push(SrcChar {
                    ch,
                    line: Some(idx),
                });
            }
        }
        let len = src.len();
        Self {
            src,
            colors: vec![Ink::Default; len],
            pos: 0,
        }
    }

    fn peek(&self) -> Option<char> {
        self.src.get(self.pos).map(|s| s.ch)
    }
    fn peek_at(&self, offset: usize) -> Option<char> {
        self.src.get(self.pos + offset).map(|s| s.ch)
    }
    fn starts_with(&self, s: &str) -> bool {
        s.chars()
            .enumerate()
            .all(|(i, c)| self.peek_at(i) == Some(c))
    }
    fn paint(&mut self, start: usize, end: usize, ink: Ink) {
        for i in start..end.min(self.colors.len()) {
            self.colors[i] = ink;
        }
    }
    fn take(&mut self, ink: Ink) -> Option<char> {
        let c = self.peek()?;
        self.colors[self.pos] = ink;
        self.pos += 1;
        Some(c)
    }
    fn text_range(&self, start: usize, end: usize) -> String {
        self.src[start..end.min(self.src.len())]
            .iter()
            .map(|s| s.ch)
            .collect()
    }

    fn is_space(c: char) -> bool {
        c == ' ' || c == '\t' || c == '\r'
    }
    fn is_delim(c: char) -> bool {
        Self::is_space(c)
            || matches!(
                c,
                '\n' | ';' | '|' | '&' | '<' | '>' | '(' | ')' | '\'' | '"' | '`' | '$' | '\\'
            )
    }

    fn has_more_on_line(&self, mut from: usize) -> bool {
        while let Some(s) = self.src.get(from) {
            if s.ch == '\n' {
                return false;
            }
            if !Self::is_space(s.ch) {
                return true;
            }
            from += 1;
        }
        false
    }

    fn next_bare_word(&self, mut from: usize) -> Option<String> {
        while let Some(s) = self.src.get(from) {
            if Self::is_space(s.ch) {
                from += 1;
            } else {
                break;
            }
        }
        if from >= self.src.len() || self.src[from].ch == '\n' || Self::is_delim(self.src[from].ch) {
            return None;
        }
        let start = from;
        while from < self.src.len() && !Self::is_delim(self.src[from].ch) {
            from += 1;
        }
        Some(self.text_range(start, from))
    }

    fn parse(&mut self) {
        let mut state = ShellState::default();
        self.parse_shell(&mut state, StopKind::Root);
    }

    fn parse_shell(&mut self, state: &mut ShellState, stop: StopKind) {
        while let Some(c) = self.peek() {
            if stop == StopKind::Backtick && c == '`' {
                self.take(Ink::Default);
                return;
            }
            match c {
                '\n' => {
                    self.take(Ink::Default);
                    state.command_start = true;
                    state.current_command.clear();
                    state.expect_fd_target = false;
                    if !state.heredoc_queue.is_empty() {
                        let queue = std::mem::take(&mut state.heredoc_queue);
                        for (delim, quoted) in queue {
                            self.parse_heredoc(&delim, quoted);
                        }
                    }
                }
                ' ' | '\t' | '\r' => {
                    self.take(Ink::Default);
                }
                '#' => {
                    let start = self.pos;
                    while let Some(ch) = self.peek() {
                        if ch == '\n' {
                            break;
                        }
                        self.pos += 1;
                    }
                    self.paint(start, self.pos, Ink::Comment);
                }
                ';' => {
                    if self.peek_at(1) == Some(';') && state.in_case_pattern {
                        self.take(Ink::Default);
                        self.take(Ink::Default);
                        state.command_start = true;
                        // in_case_pattern is reset below; it means we are now
                        // between patterns. esac is recognised in word code.
                        state.in_case_pattern = true;
                    } else {
                        self.take(Ink::Default);
                        state.command_start = true;
                    }
                    state.current_command.clear();
                    state.expect_fd_target = false;
                }
                '|' => {
                    if state.in_case_pattern && self.peek_at(1) != Some('|') {
                        self.take(Ink::Default);
                    } else {
                        self.take(Ink::Default);
                        if self.peek() == Some('|') || self.peek() == Some('&') {
                            self.take(Ink::Default);
                        }
                        state.command_start = true;
                        state.current_command.clear();
                    }
                    state.expect_fd_target = false;
                }
                '&' => {
                    if self.peek_at(1) == Some('&') {
                        self.take(Ink::Default);
                        self.take(Ink::Default);
                        state.command_start = true;
                        state.current_command.clear();
                    } else if self.peek_at(1) == Some('>') {
                        self.take(Ink::Default);
                        self.take(Ink::Default);
                        state.command_start = false;
                    } else {
                        self.take(Ink::Default);
                        state.command_start = true;
                        state.current_command.clear();
                    }
                    state.expect_fd_target = false;
                }
                '<' | '>' => {
                    self.parse_redirection(state);
                }
                '(' => {
                    if self.peek_at(1) == Some('(') && !state.in_array {
                        self.parse_arithmetic();
                        state.command_start = false;
                    } else {
                        self.take(Ink::Default);
                        state.paren_depth += 1;
                        if !state.in_array {
                            state.command_start = true;
                            state.current_command.clear();
                        }
                    }
                }
                ')' => {
                    if stop == StopKind::Paren && state.paren_depth == 0 {
                        self.take(Ink::Default);
                        return;
                    }
                    if state.paren_depth > 0 {
                        state.paren_depth -= 1;
                    }
                    if state.in_case_pattern {
                        self.take(Ink::Keyword);
                        state.in_case_pattern = false;
                        state.command_start = true;
                    } else {
                        self.take(Ink::Default);
                        state.command_start = false;
                    }
                    if state.in_array && state.paren_depth == 0 {
                        state.in_array = false;
                    }
                }
                _ => {
                    self.parse_word(state);
                }
            }
        }
    }

    fn parse_redirection(&mut self, state: &mut ShellState) {
        let start_char = self.peek().unwrap_or('<');
        if start_char == '<' && self.starts_with("<<<") {
            for _ in 0..3 {
                self.take(Ink::Default);
            }
            state.command_start = false;
            return;
        }
        if start_char == '<' && self.starts_with("<<") {
            self.take(Ink::Default);
            self.take(Ink::Default);
            if self.peek() == Some('-') {
                self.take(Ink::Default);
            }
            state.heredoc_delim_expected = true;
            state.command_start = false;
            return;
        }
        // One redirection operator, including <>, <&, >&, >>, >| and <( / >(
        self.take(Ink::Default);
        if matches!(self.peek(), Some('>') | Some('<') | Some('|')) {
            self.take(Ink::Default);
            state.expect_fd_target = false;
        } else if self.peek() == Some('&') {
            self.take(Ink::Default);
            state.expect_fd_target = true;
        } else {
            state.expect_fd_target = false;
        }
        state.command_start = false;
    }

    fn parse_escape_outside(&mut self) {
        // Backslash plus the following character.
        self.take(Ink::Builtin);
        if self.pos < self.src.len() {
            self.take(Ink::Builtin);
        }
    }

    fn parse_single_quote(&mut self, ansi: bool) {
        self.take(Ink::Default); // opening '
        while let Some(c) = self.peek() {
            if c == '\'' {
                self.take(Ink::Default);
                return;
            }
            if ansi && c == '\\' {
                self.parse_ansi_escape();
            } else {
                self.take(Ink::Str);
            }
        }
    }

    fn parse_ansi_escape(&mut self) {
        self.take(Ink::Builtin); // backslash
        let Some(c) = self.peek() else { return };
        self.take(Ink::Builtin);
        match c {
            'x' => {
                for _ in 0..2 {
                    if self.peek().map(|c| c.is_ascii_hexdigit()).unwrap_or(false) {
                        self.take(Ink::Builtin);
                    } else {
                        break;
                    }
                }
            }
            'u' => {
                for _ in 0..4 {
                    if self.peek().map(|c| c.is_ascii_hexdigit()).unwrap_or(false) {
                        self.take(Ink::Builtin);
                    } else {
                        break;
                    }
                }
            }
            'U' => {
                for _ in 0..8 {
                    if self.peek().map(|c| c.is_ascii_hexdigit()).unwrap_or(false) {
                        self.take(Ink::Builtin);
                    } else {
                        break;
                    }
                }
            }
            '0'..='7' => {
                for _ in 0..2 {
                    if self
                        .peek()
                        .map(|c| ('0'..='7').contains(&c))
                        .unwrap_or(false)
                    {
                        self.take(Ink::Builtin);
                    } else {
                        break;
                    }
                }
            }
            'c' => {
                let _ = self.take(Ink::Builtin);
            }
            _ => {}
        }
    }

    fn parse_double_quote(&mut self) {
        self.take(Ink::Default); // opening "
        while let Some(c) = self.peek() {
            match c {
                '"' => {
                    self.take(Ink::Default);
                    return;
                }
                '\\' => {
                    let next = self.peek_at(1);
                    if matches!(next, Some('$') | Some('`') | Some('"') | Some('\\') | Some('\n')) {
                        self.take(Ink::Builtin);
                        self.take(Ink::Builtin);
                    } else {
                        self.take(Ink::Str);
                    }
                }
                '$' => {
                    self.parse_dollar(true);
                }
                '`' => {
                    self.take(Ink::Default);
                    let mut nested = ShellState::default();
                    self.parse_shell(&mut nested, StopKind::Backtick);
                }
                _ => {
                    self.take(Ink::Str);
                }
            }
        }
    }

    fn parse_dollar(&mut self, in_double: bool) {
        self.take(Ink::Default); // $
        match self.peek() {
            Some('\'') if !in_double => self.parse_single_quote(true),
            Some('"') if !in_double => self.parse_double_quote(),
            Some('(') => {
                if self.peek_at(1) == Some('(') {
                    self.parse_arithmetic();
                } else {
                    self.take(Ink::Default); // (
                    let mut nested = ShellState::default();
                    self.parse_shell(&mut nested, StopKind::Paren);
                }
            }
            Some('{') => self.parse_brace(),
            Some('[') => {
                self.take(Ink::Keyword);
                while let Some(c) = self.peek() {
                    if c == ']' {
                        self.take(Ink::Keyword);
                        break;
                    }
                    if c == '$' {
                        self.parse_dollar(false);
                    } else if c == '\'' {
                        self.parse_single_quote(false);
                    } else if c == '"' {
                        self.parse_double_quote();
                    } else {
                        self.take(Ink::Default);
                    }
                }
            }
            Some(c) if c == '_' || c.is_ascii_alphabetic() => {
                let start = self.pos;
                while let Some(ch) = self.peek() {
                    if ch == '_' || ch.is_ascii_alphanumeric() {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                self.paint(start, self.pos, Ink::Var);
            }
            Some(c)
                if c.is_ascii_digit() || matches!(c, '@' | '*' | '#' | '?' | '$' | '!' | '-') =>
            {
                self.take(Ink::Var);
            }
            _ => {}
        }
    }

    fn parse_brace(&mut self) {
        self.take(Ink::Default); // {
        // Length/indirection markers, unless they are the variable itself.
        if self.peek() == Some('#') && self.peek_at(1) != Some('}') {
            self.take(Ink::Default);
        } else if self.peek() == Some('!') && self.peek_at(1) != Some('}') {
            self.take(Ink::Default);
        }
        // The variable name or a special variable.
        match self.peek() {
            Some(c) if c == '_' || c.is_ascii_alphabetic() => {
                let start = self.pos;
                while let Some(ch) = self.peek() {
                    if ch == '_' || ch.is_ascii_alphanumeric() {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                self.paint(start, self.pos, Ink::Var);
            }
            Some(c)
                if c.is_ascii_digit() || matches!(c, '@' | '*' | '#' | '?' | '$' | '!' | '-') =>
            {
                self.take(Ink::Var);
            }
            _ => {}
        }
        // An array subscript.
        if self.peek() == Some('[') {
            self.take(Ink::Var);
            while let Some(c) = self.peek() {
                if c == ']' {
                    self.take(Ink::Var);
                    break;
                }
                if c.is_ascii_digit() {
                    let start = self.pos;
                    while self.peek().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                        self.pos += 1;
                    }
                    self.paint(start, self.pos, Ink::Number);
                } else {
                    self.take(Ink::Var);
                }
            }
        }
        let mut depth = 1usize;
        while let Some(c) = self.peek() {
            match c {
                '{' => {
                    depth += 1;
                    self.take(Ink::Default);
                }
                '}' => {
                    depth -= 1;
                    self.take(Ink::Default);
                    if depth == 0 {
                        return;
                    }
                }
                '$' => self.parse_dollar(false),
                '\'' => self.parse_single_quote(false),
                '"' => self.parse_double_quote(),
                '`' => {
                    self.take(Ink::Default);
                    let mut nested = ShellState::default();
                    self.parse_shell(&mut nested, StopKind::Backtick);
                }
                _ => {
                    self.take(Ink::Default);
                }
            }
        }
    }

    fn parse_arithmetic(&mut self) {
        // Consume the opening (( and then a balance count of two.
        self.take(Ink::Default);
        self.take(Ink::Default);
        let mut depth = 2usize;
        while let Some(c) = self.peek() {
            match c {
                '(' => {
                    depth += 1;
                    self.take(Ink::Default);
                }
                ')' => {
                    depth = depth.saturating_sub(1);
                    self.take(Ink::Default);
                    if depth == 0 {
                        return;
                    }
                }
                '$' => self.parse_dollar(false),
                '\'' => self.parse_single_quote(false),
                '"' => self.parse_double_quote(),
                '`' => {
                    self.take(Ink::Default);
                    let mut nested = ShellState::default();
                    self.parse_shell(&mut nested, StopKind::Backtick);
                }
                _ if c.is_ascii_digit() => {
                    let start = self.pos;
                    while let Some(ch) = self.peek() {
                        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '#' || ch == '@' {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                    self.paint(start, self.pos, Ink::Number);
                }
                _ => {
                    self.take(Ink::Default);
                }
            }
        }
    }

    fn parse_heredoc(&mut self, delim: &str, quoted: bool) {
        loop {
            if self.pos >= self.src.len() {
                return;
            }
            let line_start = self.pos;
            let mut end = self.pos;
            while end < self.src.len() && self.src[end].ch != '\n' {
                end += 1;
            }
            let line_text = self.text_range(line_start, end);
            if line_text == delim {
                self.paint(line_start, end, Ink::Keyword);
                self.pos = end;
                return;
            }
            while self.pos < end {
                if !quoted && self.peek() == Some('$') {
                    self.parse_dollar(false);
                } else if !quoted && self.peek() == Some('`') {
                    self.take(Ink::Default);
                    let mut nested = ShellState::default();
                    self.parse_shell(&mut nested, StopKind::Backtick);
                } else {
                    self.take(Ink::Str);
                }
            }
            if self.peek() == Some('\n') {
                self.take(Ink::Default);
            } else {
                return;
            }
        }
    }

    fn paint_arithmetic_segment(&mut self, start: usize, end: usize) {
        self.paint(start, end, Ink::Default);
        let mut i = start;
        while i < end {
            if self.src[i].ch.is_ascii_digit() {
                let s = i;
                while i < end
                    && (self.src[i].ch.is_ascii_alphanumeric()
                        || self.src[i].ch == '_'
                        || self.src[i].ch == '#')
                {
                    i += 1;
                }
                self.paint(s, i, Ink::Number);
            } else {
                i += 1;
            }
        }
    }

    fn option_len(segment: &str, current_command: &str) -> Option<usize> {
        let chars: Vec<char> = segment.chars().collect();
        if chars.first() != Some(&'-') {
            return None;
        }
        if current_command == "echo" {
            if chars.len() >= 2
                && chars[1] != '-'
                && chars[1..]
                    .iter()
                    .take_while(|c| **c != '=')
                    .all(|c| matches!(c, 'n' | 'e' | 'E'))
            {
                let mut n = 1;
                while n < chars.len() && matches!(chars[n], 'n' | 'e' | 'E') {
                    n += 1;
                }
                return if n > 1 { Some(n) } else { None };
            }
            return None;
        }
        if chars.len() >= 3 && chars[1] == '-' {
            if !(chars[2].is_ascii_alphanumeric() || chars[2] == '_') {
                return None;
            }
            let mut n = 2;
            while n < chars.len()
                && (chars[n].is_ascii_alphanumeric() || chars[n] == '_' || chars[n] == '-')
            {
                n += 1;
            }
            return Some(n);
        }
        if chars.len() >= 2 && (chars[1].is_ascii_alphanumeric() || chars[1] == '_') {
            let mut n = 1;
            while n < chars.len() && (chars[n].is_ascii_alphanumeric() || chars[n] == '_') {
                n += 1;
            }
            return Some(n);
        }
        None
    }

    fn is_identifier(s: &str) -> bool {
        let mut chars = s.chars();
        match chars.next() {
            Some(c) if c == '_' || c.is_ascii_alphabetic() => {}
            _ => return false,
        }
        chars.all(|c| c == '_' || c.is_ascii_alphanumeric())
    }

    fn parse_word(&mut self, state: &mut ShellState) {
        let word_start_pos = self.pos;
        let was_command_start = state.command_start;
        let heredoc_word = state.heredoc_delim_expected;
        let mut first = true;
        let mut command_name_from_word: Option<String> = None;
        let mut after_word_command_start: Option<bool> = None;

        // Stage handling for a for-variable / case subject happens through
        // bare-segment classification below; expansions simply advance it.
        let mut stage_consumed = false;

        while let Some(c) = self.peek() {
            if Self::is_space(c) || c == '\n' {
                break;
            }
            // Separators which end a word.
            if matches!(c, ';' | '|' | '&' | '<' | '>' | '(' | ')') {
                break;
            }
            match c {
                '\'' => {
                    self.parse_single_quote(false);
                    first = false;
                }
                '"' => {
                    self.parse_double_quote();
                    first = false;
                }
                '`' => {
                    self.take(Ink::Default);
                    let mut nested = ShellState::default();
                    self.parse_shell(&mut nested, StopKind::Backtick);
                    first = false;
                }
                '$' => {
                    self.parse_dollar(false);
                    first = false;
                }
                '\\' => {
                    self.parse_escape_outside();
                    first = false;
                }
                _ => {
                    let start = self.pos;
                    while let Some(ch) = self.peek() {
                        if Self::is_delim(ch) {
                            break;
                        }
                        self.pos += 1;
                    }
                    let segment = self.text_range(start, self.pos);

                    if heredoc_word && first {
                        self.paint(start, self.pos, Ink::Keyword);
                    } else if state.for_stage == 1 {
                        self.paint(start, self.pos, Ink::Default);
                        state.for_stage = 2;
                        stage_consumed = true;
                    } else if state.for_stage == 2 && segment == "in" {
                        self.paint(start, self.pos, Ink::Keyword);
                        state.for_stage = 0;
                        stage_consumed = true;
                    } else if state.case_stage == 1 {
                        self.paint(start, self.pos, Ink::Default);
                        state.case_stage = 2;
                        stage_consumed = true;
                    } else if state.case_stage == 2 && segment == "in" {
                        self.paint(start, self.pos, Ink::Keyword);
                        state.case_stage = 0;
                        state.in_case_pattern = true;
                        stage_consumed = true;
                    } else if state.in_case_pattern {
                        if segment == "esac" {
                            self.paint(start, self.pos, Ink::Keyword);
                            state.in_case_pattern = false;
                            after_word_command_start = Some(false);
                        } else {
                            self.paint(start, self.pos, Ink::Default);
                        }
                    } else if first {
                        // Assignment?
                        let assignment = self.try_paint_assignment(
                            state,
                            start,
                            self.pos,
                            &segment,
                            was_command_start,
                        );
                        if assignment {
                            if was_command_start {
                                after_word_command_start = Some(true);
                            } else {
                                after_word_command_start = Some(false);
                            }
                            // An array assignment continues with '('.
                            if segment.ends_with('=') && self.peek() == Some('(') {
                                state.in_array = true;
                            }
                        } else if was_command_start {
                            let info = self.paint_command_segment(state, start, self.pos, &segment);
                            command_name_from_word = info.0;
                            after_word_command_start = Some(info.1);
                        } else {
                            self.paint_argument_segment(state, start, self.pos, &segment);
                            after_word_command_start = Some(false);
                        }
                    } else {
                        // A later bare part of the same word.
                        if state.current_command == "let" {
                            self.paint_arithmetic_segment(start, self.pos);
                        } else {
                            self.paint(start, self.pos, Ink::Default);
                        }
                    }
                    first = false;
                }
            }
        }

        // Stage advancement for words made entirely of expansions/quotes.
        if !stage_consumed {
            if state.for_stage == 1 {
                state.for_stage = 2;
            } else if state.case_stage == 1 {
                state.case_stage = 2;
            }
        }

        if heredoc_word {
            let raw = self.text_range(word_start_pos, self.pos);
            let quoted = raw.contains('\'') || raw.contains('"') || raw.contains('\\');
            let delim: String = raw
                .chars()
                .filter(|c| !matches!(c, '\'' | '"' | '\\'))
                .collect();
            state.heredoc_delim_expected = false;
            state.heredoc_queue.push((delim, quoted));
            state.command_start = false;
            return;
        }

        if let Some(name) = command_name_from_word {
            state.current_command = name;
        }
        if let Some(next) = after_word_command_start {
            state.command_start = next;
            if next {
                // Keywords such as `if`/`then` are not the current command
                // for argument purposes. paint_command_segment signals this
                // by not providing a name (handled through state below).
            }
        } else if was_command_start {
            state.command_start = false;
        }
        state.expect_fd_target = false;
        let _ = word_start_pos;
    }

    fn try_paint_assignment(
        &mut self,
        state: &ShellState,
        start: usize,
        end: usize,
        segment: &str,
        was_command_start: bool,
    ) -> bool {
        let Some(eq_rel) = segment.find('=') else {
            return false;
        };
        let name = &segment[..eq_rel];
        if !Self::is_identifier(name) {
            return false;
        }
        let declaration = matches!(
            state.current_command.as_str(),
            "declare" | "local" | "export" | "readonly" | "typeset"
        );
        if !was_command_start && !declaration {
            return false;
        }
        let eq_pos = start + segment[..eq_rel].chars().count();
        self.paint(start, eq_pos, Ink::Var);
        self.paint(eq_pos, eq_pos + 1, Ink::Default);
        if eq_pos + 1 < end {
            self.paint(eq_pos + 1, end, Ink::Str);
        }
        true
    }

    /// Returns (current command name to remember, next word is a command).
    fn paint_command_segment(
        &mut self,
        state: &mut ShellState,
        start: usize,
        end: usize,
        segment: &str,
    ) -> (Option<String>, bool) {
        let has_more = self.has_more_on_line(end);
        let followed_by_word = self.next_bare_word(end).is_some() || {
            // A following expansion/quote is also something.
            let mut p = end;
            while p < self.src.len() && Self::is_space(self.src[p].ch) {
                p += 1;
            }
            p < self.src.len() && self.src[p].ch != '\n'
        };

        match segment {
            "then" | "return" => {
                self.paint(start, end, Ink::Keyword);
                return (None, true);
            }
            "if" | "elif" | "while" | "until" | "else" | "do" if followed_by_word => {
                self.paint(start, end, Ink::Keyword);
                return (None, true);
            }
            "for" if followed_by_word => {
                self.paint(start, end, Ink::Keyword);
                state.for_stage = 1;
                return (None, false);
            }
            "case" if followed_by_word => {
                self.paint(start, end, Ink::Keyword);
                state.case_stage = 1;
                return (None, false);
            }
            "function" if followed_by_word => {
                self.paint(start, end, Ink::Keyword);
                return (None, true);
            }
            "declare" | "local" | "export" | "readonly" | "typeset" if followed_by_word => {
                self.paint(start, end, Ink::Keyword);
                return (Some(segment.to_string()), false);
            }
            "alias" if followed_by_word => {
                self.paint(start, end, Ink::Builtin);
                return (Some(segment.to_string()), false);
            }
            "[" | "[[" if has_more => {
                self.paint(start, end, Ink::Builtin);
                return (Some(segment.to_string()), false);
            }
            "{" if has_more => {
                self.paint(start, end, Ink::Default);
                return (None, true);
            }
            "}" => {
                self.paint(start, end, Ink::Default);
                return (None, false);
            }
            _ => {}
        }

        if BUILTINS.contains(&segment) {
            self.paint(start, end, Ink::Builtin);
        } else {
            self.paint(start, end, Ink::Command);
        }
        (Some(segment.to_string()), false)
    }

    fn paint_argument_segment(
        &mut self,
        state: &ShellState,
        start: usize,
        end: usize,
        segment: &str,
    ) {
        if state.expect_fd_target && segment.chars().all(|c| c.is_ascii_digit()) && !segment.is_empty() {
            self.paint(start, end, Ink::Number);
            return;
        }
        if state.current_command == "let" {
            self.paint_arithmetic_segment(start, end);
            return;
        }
        if matches!(
            state.current_command.as_str(),
            "declare" | "local" | "export" | "readonly" | "typeset"
        ) && Self::is_identifier(segment)
        {
            self.paint(start, end, Ink::Var);
            return;
        }
        if state.current_command == "alias" && !segment.starts_with('-') {
            if let Some(eq) = segment.find('=') {
                let eq_pos = start + segment[..eq].chars().count();
                self.paint(start, eq_pos, Ink::Command);
                self.paint(eq_pos, end, Ink::Default);
            } else {
                self.paint(start, end, Ink::Command);
            }
            return;
        }
        if (state.current_command == "[" && segment == "]")
            || (state.current_command == "[[" && segment == "]]")
        {
            self.paint(start, end, Ink::Builtin);
            return;
        }
        if let Some(n) = Self::option_len(segment, &state.current_command) {
            let opt_end = start + n;
            self.paint(start, opt_end, Ink::Var);
            if opt_end < end {
                self.paint(opt_end, end, Ink::Default);
            }
            return;
        }
        self.paint(start, end, Ink::Default);
        // ~ at the start of a word.
        if segment.starts_with('~') {
            self.paint(start, start + 1, Ink::Var);
        }
        // A glob character class: only its brackets are highlighted.
        let chars: Vec<char> = segment.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            if chars[i] == '[' {
                if let Some(rel) = chars[i + 1..].iter().position(|c| *c == ']') {
                    let close = i + 1 + rel;
                    self.paint(start + i, start + i + 1, Ink::Keyword);
                    self.paint(start + close, start + close + 1, Ink::Keyword);
                    i = close + 1;
                    continue;
                }
            }
            i += 1;
        }
    }

    fn into_lines(self, line_count: usize) -> Vec<Line<'static>> {
        let mut out: Vec<Vec<(Ink, String)>> = vec![Vec::new(); line_count];
        for (idx, src) in self.src.iter().enumerate() {
            if let Some(line_idx) = src.line {
                let ink = self.colors[idx];
                let spans = &mut out[line_idx];
                if let Some((last_ink, text)) = spans.last_mut() {
                    if *last_ink == ink {
                        text.push(src.ch);
                        continue;
                    }
                }
                spans.push((ink, src.ch.to_string()));
            }
        }
        out.into_iter()
            .map(|spans| {
                Line::from(
                    spans
                        .into_iter()
                        .map(|(ink, text)| Span::styled(text, Style::default().fg(ink.color())))
                        .collect::<Vec<_>>(),
                )
            })
            .collect()
    }
}

pub fn highlight_lines(lines: &[String]) -> Vec<Line<'static>> {
    let mut highlighter = Highlighter::new(lines);
    highlighter.parse();
    highlighter.into_lines(lines.len())
}
RS"}

