use std::collections::HashMap;
use std::io::{self, Write};
use std::process::{Command, Stdio};

use crossterm::{
    execute,
    event::{KeyCode, KeyEvent, KeyModifiers},
    terminal::{EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::Terminal;
use ratatui::backend::CrosstermBackend;
use ratatui::widgets::ListState;

use crate::commandlist::CommandList;
use crate::executor::{run_command_sync, Executor};
use crate::pipr_config::PiprConfig;
use crate::textfield::TextField;

pub const SPINNER_FRAMES: [&str; 6] = ["⠟", "⠯", "⠷", "⠾", "⠽", "⠻"];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ListKind {
    History,
    Bookmarks,
}

#[derive(Debug)]
pub struct CmdListView {
    pub kind: ListKind,
    pub entries: Vec<String>,
    pub selected: Option<usize>,
    pub deleted: Vec<String>,
    pub state: ListState,
}

impl CmdListView {
    pub fn new(kind: ListKind, entries: Vec<String>) -> Self {
        let selected = if entries.is_empty() {
            None
        } else {
            Some(entries.len() - 1)
        };
        let mut state = ListState::default();
        state.select(selected);
        Self {
            kind,
            entries,
            selected,
            deleted: Vec::new(),
            state,
        }
    }

    pub fn sync_state(&mut self) {
        self.state.select(self.selected);
    }

    pub fn selected_entry(&self) -> Option<&str> {
        self.selected.and_then(|i| self.entries.get(i)).map(|s| s.as_str())
    }

    fn move_by(&mut self, delta: isize) {
        if let Some(sel) = self.selected {
            if self.entries.is_empty() {
                self.selected = None;
                return;
            }
            let next = sel as isize + delta;
            self.selected = Some(next.clamp(0, self.entries.len() as isize - 1) as usize);
            self.sync_state();
        }
    }

    fn delete_selected(&mut self) {
        if let Some(idx) = self.selected {
            if idx < self.entries.len() {
                let removed = self.entries.remove(idx);
                self.deleted.push(removed);
                self.selected = if self.entries.is_empty() {
                    None
                } else if idx >= self.entries.len() {
                    Some(self.entries.len() - 1)
                } else {
                    Some(idx)
                };
                self.sync_state();
            }
        }
    }

    fn undo(&mut self) {
        if let Some(item) = self.deleted.pop() {
            self.entries.push(item);
        }
        if !self.entries.is_empty() {
            self.selected = Some(self.entries.len() - 1);
            self.sync_state();
        }
    }
}

#[derive(Debug)]
pub enum AppMode {
    Main,
    Help,
    CmdList(CmdListView),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChooserKind {
    Snippet,
    HelpViewer,
    OutputViewer,
}

#[derive(Debug, Clone)]
pub struct Chooser {
    pub kind: ChooserKind,
    pub options: HashMap<char, String>,
}

#[derive(Debug, Clone)]
pub enum ExternalAction {
    Help(String),
    Output(String, String),
}

#[derive(Debug, Clone)]
struct Cached {
    prefix_with_pipe: String,
    output: String,
}

pub struct App {
    pub config: PiprConfig,
    pub input: TextField,
    pub mode: AppMode,
    pub chooser: Option<Chooser>,
    pub command_output: String,
    pub error_output: Option<String>,
    pub last_evaluated_input: String,
    pub is_evaluating: bool,
    pub spinner_idx: usize,
    pub autoeval: bool,
    pub paranoid: bool,
    pub should_quit: bool,
    pub pending_external: Option<ExternalAction>,
    history: CommandList,
    bookmarks: CommandList,
    history_index: Option<usize>,
    cached: Option<Cached>,
    executor: Executor,
    isolation: bool,
}

impl App {
    pub fn new(
        config: PiprConfig,
        history: CommandList,
        bookmarks: CommandList,
        initial: &str,
        isolation: bool,
    ) -> Self {
        let autoeval = config.autoeval_mode_default;
        let paranoid = config.paranoid_history_mode_default;
        let executor = Executor::new(config.clone(), isolation);
        let mut input = TextField::default();
        input.set_content(initial);
        Self {
            config,
            input,
            mode: AppMode::Main,
            chooser: None,
            command_output: String::new(),
            error_output: None,
            last_evaluated_input: String::new(),
            is_evaluating: false,
            spinner_idx: 0,
            autoeval,
            paranoid,
            should_quit: false,
            pending_external: None,
            history,
            bookmarks,
            history_index: None,
            cached: None,
            executor,
            isolation,
        }
    }

    pub fn is_bookmarked(&self) -> bool {
        let content = self.input.get_content();
        self.bookmarks.entries.iter().any(|e| e == &content)
    }

    pub fn is_caching(&self) -> bool {
        self.cached.is_some()
    }

    pub fn validate_cache(&mut self) {
        if let Some(cached) = &self.cached {
            if !self.input.get_content().starts_with(&cached.prefix_with_pipe) {
                self.cached = None;
            }
        }
    }

    pub fn on_tick(&mut self) {
        if self.is_evaluating {
            self.spinner_idx = (self.spinner_idx + 1) % SPINNER_FRAMES.len();
        }
    }

    pub fn poll_evaluations(&mut self) {
        let results = self.executor.poll_results();
        for result in results {
            self.is_evaluating = false;
            if result.success {
                self.command_output = result.stdout;
                self.error_output = None;
                if self.paranoid {
                    self.history.add(&result.submitted_input);
                }
            } else {
                self.error_output = Some(result.stderr);
            }
        }
    }

    fn process_command(raw: &str) -> String {
        raw.lines()
            .filter(|line| !line.starts_with('#'))
            .collect::<Vec<_>>()
            .join(" ")
    }

    fn start_evaluation(&mut self) {
        self.validate_cache();
        let raw = self.input.get_content();
        let (shell_command, stdin_data) = if let Some(cached) = &self.cached {
            let suffix = &raw[cached.prefix_with_pipe.len()..];
            (Self::process_command(suffix), cached.output.clone())
        } else {
            (Self::process_command(&raw), String::new())
        };
        self.last_evaluated_input = raw.clone();
        self.is_evaluating = true;
        self.spinner_idx = 0;
        self.executor.launch(raw, shell_command, stdin_data);
    }

    fn maybe_autoeval(&mut self) {
        if self.autoeval && self.input.get_content() != self.last_evaluated_input {
            self.start_evaluation();
        }
    }

    fn open_cmdlist(&mut self, kind: ListKind) {
        self.history.add(&self.input.get_content());
        let entries = match kind {
            ListKind::History => self.history.entries.clone(),
            ListKind::Bookmarks => self.bookmarks.entries.clone(),
        };
        self.mode = AppMode::CmdList(CmdListView::new(kind, entries));
    }

    fn close_cmdlist(&mut self, select: bool) {
        let old_mode = std::mem::replace(&mut self.mode, AppMode::Main);
        if let AppMode::CmdList(view) = old_mode {
            let selected_idx = view.selected;
            let selected_entry = view.selected_entry().map(|s| s.to_string());
            match view.kind {
                ListKind::History => {
                    self.history.set_entries_and_save(view.entries);
                    if select {
                        if let (Some(idx), Some(entry)) = (selected_idx, selected_entry) {
                            self.input.set_content(&entry);
                            self.history_index = Some(idx);
                        }
                    }
                }
                ListKind::Bookmarks => {
                    self.bookmarks.set_entries_and_save(view.entries);
                    if select {
                        if let Some(entry) = selected_entry {
                            self.input.set_content(&entry);
                        }
                    }
                }
            }
        }
    }

    fn word_under_cursor(&self) -> Option<String> {
        let line = self.input.lines.get(self.input.cursor_y)?;
        let cursor = self.input.cursor_x;
        let mut start = 0usize;
        for part in line.split(' ') {
            let part_len = part.chars().count();
            if cursor <= start + part_len {
                if part.is_empty() {
                    return None;
                }
                return Some(part.to_string());
            }
            start += part_len + 1;
        }
        None
    }

    fn open_help_chooser(&mut self) {
        if let Some(word) = self.word_under_cursor() {
            let options = self
                .config
                .help_viewers
                .iter()
                .map(|(k, v)| (*k, v.replace("??", &word)))
                .collect();
            self.chooser = Some(Chooser {
                kind: ChooserKind::HelpViewer,
                options,
            });
        }
    }

    fn cache_at_pipe(&mut self) {
        let content = self.input.get_content();
        let abs = self.input.absolute_cursor_char();
        let mut cursor_byte = None;
        for (char_idx, (byte_idx, ch)) in content.char_indices().enumerate() {
            if char_idx == abs {
                if ch != '|' {
                    return;
                }
                cursor_byte = Some(byte_idx);
                break;
            }
        }
        let Some(cursor_byte) = cursor_byte else { return };
        let prefix_raw = &content[..cursor_byte];
        let prefix_with_pipe = content[..cursor_byte + 1].to_string();
        let processed = Self::process_command(prefix_raw);
        match run_command_sync(&self.config, self.isolation, &processed) {
            Ok(output) => {
                self.cached = Some(Cached {
                    prefix_with_pipe,
                    output,
                });
            }
            Err(e) => {
                self.error_output = Some(format!("could not run command to cache: {}", e));
            }
        }
    }

    fn history_previous(&mut self) {
        if self.history.entries.is_empty() {
            return;
        }
        let target = if let Some(idx) = self.history_index {
            idx.saturating_sub(1)
        } else {
            let current = self.input.get_content();
            let will_add = !current.is_empty()
                && self.history.entries.last().map(|s| s.as_str()) != Some(current.as_str());
            if will_add {
                self.history.add(&current);
                if self.history.entries.is_empty() {
                    return;
                }
                self.history.entries.len().saturating_sub(2)
            } else {
                self.history.entries.len() - 1
            }
        };
        if let Some(entry) = self.history.entries.get(target).cloned() {
            self.history_index = Some(target);
            self.input.set_content(&entry);
        }
    }

    fn history_next(&mut self) {
        if self.history.entries.is_empty() {
            return;
        }
        if let Some(idx) = self.history_index {
            if idx + 1 >= self.history.entries.len().saturating_sub(1) {
                self.history_index = None;
                self.input.set_content("");
            } else {
                let target = idx + 1;
                if let Some(entry) = self.history.entries.get(target).cloned() {
                    self.history_index = Some(target);
                    self.input.set_content(&entry);
                }
            }
        }
    }

    fn toggle_bookmark(&mut self) {
        let current = self.input.get_content();
        if current.is_empty() {
            return;
        }
        if !self.bookmarks.remove_first(&current) {
            self.bookmarks.add(&current);
        }
    }

    fn finish_history_add(&mut self) {
        self.history.add(&self.input.get_content());
    }

    pub fn finish_input(&self) -> String {
        self.input.get_content()
    }

    pub fn add_final_to_history(&mut self) {
        self.finish_history_add();
    }

    fn handle_list_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Esc => self.close_cmdlist(false),
            KeyCode::Enter => self.close_cmdlist(true),
            KeyCode::Up => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.move_by(-1);
                }
            }
            KeyCode::Down => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.move_by(1);
                }
            }
            KeyCode::PageUp => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.move_by(-5);
                }
            }
            KeyCode::PageDown => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.move_by(5);
                }
            }
            KeyCode::Backspace | KeyCode::Delete => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.delete_selected();
                }
            }
            KeyCode::Char(c) => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    match c {
                        'k' => view.move_by(-1),
                        'j' => view.move_by(1),
                        'g' => view.move_by(-5),
                        'G' => view.move_by(5),
                        'u' => view.undo(),
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }

    fn handle_text_key(&mut self, key: KeyEvent) -> bool {
        let before = self.input.get_content();
        let handled = match key.code {
            KeyCode::Char(c) => {
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    match c {
                        'a' => self.input.home(),
                        'e' => self.input.end(),
                        'u' | 'x' => self.input.clear(),
                        'w' => self.input.delete_word(),
                        _ => self.input.insert_char(c),
                    }
                } else {
                    self.input.insert_char(c);
                }
                true
            }
            KeyCode::Backspace => {
                self.input.backspace();
                true
            }
            KeyCode::Delete => {
                self.input.delete();
                true
            }
            KeyCode::Left => {
                self.input.move_left();
                true
            }
            KeyCode::Right => {
                self.input.move_right();
                true
            }
            KeyCode::Up => {
                self.input.move_up();
                true
            }
            KeyCode::Down => {
                self.input.move_down();
                true
            }
            KeyCode::Home => {
                self.input.home();
                true
            }
            KeyCode::End => {
                self.input.end();
                true
            }
            KeyCode::Insert => {
                self.input.insert_newline();
                true
            }
            KeyCode::Enter if key.modifiers.contains(KeyModifiers::ALT) => {
                self.input.insert_newline();
                true
            }
            _ => false,
        };
        if handled {
            self.history_index = None;
            if self.input.get_content() != before {
                self.maybe_autoeval();
            }
        }
        handled
    }

    pub fn handle_key(&mut self, key: KeyEvent) {
        // Global mode switches.
        if key.code == KeyCode::F(1) {
            self.mode = if matches!(self.mode, AppMode::Help) {
                AppMode::Main
            } else {
                AppMode::Help
            };
            return;
        }
        if key.code == KeyCode::F(4) {
            if matches!(
                self.mode,
                AppMode::CmdList(CmdListView {
                    kind: ListKind::History,
                    ..
                })
            ) {
                self.mode = AppMode::Main;
            } else {
                self.open_cmdlist(ListKind::History);
            }
            return;
        }
        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('b') {
            if matches!(
                self.mode,
                AppMode::CmdList(CmdListView {
                    kind: ListKind::Bookmarks,
                    ..
                })
            ) {
                self.mode = AppMode::Main;
            } else {
                self.open_cmdlist(ListKind::Bookmarks);
            }
            return;
        }

        match self.mode {
            AppMode::Help => {
                self.mode = AppMode::Main;
            }
            AppMode::CmdList(_) => {
                self.handle_list_key(key);
            }
            AppMode::Main => {
                if let Some(chooser) = self.chooser.take() {
                    if let KeyCode::Char(c) = key.code {
                        if let Some(value) = chooser.options.get(&c).cloned() {
                            match chooser.kind {
                                ChooserKind::Snippet => {
                                    self.input.insert_snippet(&value);
                                }
                                ChooserKind::HelpViewer => {
                                    self.pending_external = Some(ExternalAction::Help(value));
                                }
                                ChooserKind::OutputViewer => {
                                    self.pending_external = Some(ExternalAction::Output(
                                        value,
                                        self.command_output.clone(),
                                    ));
                                }
                            }
                        }
                    }
                    return;
                }

                if key.code == KeyCode::Esc
                    || (key.modifiers.contains(KeyModifiers::CONTROL)
                        && matches!(key.code, KeyCode::Char('c') | KeyCode::Char('q')))
                {
                    self.should_quit = true;
                    return;
                }

                match key.code {
                    KeyCode::F(2) => {
                        self.autoeval = !self.autoeval;
                    }
                    KeyCode::F(3) => {
                        self.paranoid = !self.paranoid;
                    }
                    KeyCode::F(5) => {
                        self.open_help_chooser();
                    }
                    KeyCode::F(6) => {
                        self.chooser = Some(Chooser {
                            kind: ChooserKind::OutputViewer,
                            options: self.config.output_viewers.clone(),
                        });
                    }
                    KeyCode::F(7) => {
                        self.cache_at_pipe();
                    }
                    KeyCode::Enter if !key.modifiers.contains(KeyModifiers::ALT) => {
                        self.history_index = None;
                        self.history.add(&self.input.get_content());
                        self.start_evaluation();
                    }
                    KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.toggle_bookmark();
                    }
                    KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.history_previous();
                    }
                    KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.history_next();
                    }
                    KeyCode::Char('v') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.chooser = Some(Chooser {
                            kind: ChooserKind::Snippet,
                            options: self.config.snippets.clone(),
                        });
                    }
                    _ => {
                        self.handle_text_key(key);
                    }
                }
            }
        }
    }
}

pub fn run_external_action(
    action: &ExternalAction,
    terminal: &mut Terminal<CrosstermBackend<io::Stderr>>,
) -> io::Result<()> {
    execute!(io::stdout(), LeaveAlternateScreen)?;
    match action {
        ExternalAction::Help(command) => {
            let _ = Command::new("bash").arg("-c").arg(command).status()?;
        }
        ExternalAction::Output(program, output) => {
            let mut child = Command::new(program).stdin(Stdio::piped()).spawn()?;
            if let Some(mut stdin) = child.stdin.take() {
                stdin.write_all(output.as_bytes())?;
            }
            let _ = child.wait()?;
        }
    }
    execute!(io::stdout(), EnterAlternateScreen)?;
    terminal.clear()?;
    Ok(())
}
RS"}

