        }
    }

    fn open_cmdlist(&mut self, kind: ListKind) {
        self.history.add(&self.input.get_content());
        let entries = match kind {
            ListKind::History => self.history.entries.clone(),
            ListKind::Bookmarks => self.bookmarks.entries.clone(),
        };
        self.mode = AppMode::CmdList(CmdListView::new(kind, entries));
    }

    fn close_cmdlist(&mut self, select: bool) {
        let old_mode = std::mem::replace(&mut self.mode, AppMode::Main);
        if let AppMode::CmdList(view) = old_mode {
            let selected_idx = view.selected;
            let selected_entry = view.selected_entry().map(|s| s.to_string());
            match view.kind {
                ListKind::History => {
                    self.history.set_entries_and_save(view.entries);
                    if select {
                        if let (Some(idx), Some(entry)) = (selected_idx, selected_entry) {
                            self.input.set_content(&entry);
                            self.history_index = Some(idx);
                        }
                    }
                }
                ListKind::Bookmarks => {
                    self.bookmarks.set_entries_and_save(view.entries);
                    if select {
                        if let Some(entry) = selected_entry {
                            self.input.set_content(&entry);
                        }
                    }
                }
            }
        }
    }

    fn word_under_cursor(&self) -> Option<String> {
        let line = self.input.lines.get(self.input.cursor_y)?;
        let cursor = self.input.cursor_x;
        let mut start = 0usize;
        for part in line.split(' ') {
            let part_len = part.chars().count();
            if cursor <= start + part_len {
                if part.is_empty() {
                    return None;
                }
                return Some(part.to_string());
            }
            start += part_len + 1;
        }
        None
    }

    fn open_help_chooser(&mut self) {
        if let Some(word) = self.word_under_cursor() {
            let options = self
                .config
                .help_viewers
                .iter()
                .map(|(k, v)| (*k, v.replace("??", &word)))
                .collect();
            self.chooser = Some(Chooser {
                kind: ChooserKind::HelpViewer,
                options,
            });
        }
    }

    fn cache_at_pipe(&mut self) {
        let content = self.input.get_content();
        let abs = self.input.absolute_cursor_char();
        let mut cursor_byte = None;
        for (char_idx, (byte_idx, ch)) in content.char_indices().enumerate() {
            if char_idx == abs {
                if ch != '|' {
                    return;
                }
                cursor_byte = Some(byte_idx);
                break;
            }
        }
        let Some(cursor_byte) = cursor_byte else { return };
        let prefix_raw = &content[..cursor_byte];
        let prefix_with_pipe = content[..cursor_byte + 1].to_string();
        let processed = Self::process_command(prefix_raw);
        match run_command_sync(&self.config, self.isolation, &processed) {
            Ok(output) => {
                self.cached = Some(Cached {
                    prefix_with_pipe,
                    output,
                });
            }
            Err(e) => {
                self.error_output = Some(format!("could not run command to cache: {}", e));
            }
        }
    }

    fn history_previous(&mut self) {
        if self.history.entries.is_empty() {
            return;
        }
        let target = if let Some(idx) = self.history_index {
            idx.saturating_sub(1)
        } else {
            let current = self.input.get_content();
            let will_add = !current.is_empty()
                && self.history.entries.last().map(|s| s.as_str()) != Some(current.as_str());
            if will_add {
                self.history.add(&current);
                if self.history.entries.is_empty() {
                    return;
                }
                self.history.entries.len().saturating_sub(2)
            } else {
                self.history.entries.len() - 1
            }
        };
        if let Some(entry) = self.history.entries.get(target).cloned() {
            self.history_index = Some(target);
            self.input.set_content(&entry);
        }
    }

    fn history_next(&mut self) {
        if self.history.entries.is_empty() {
            return;
        }
        if let Some(idx) = self.history_index {
            if idx + 1 >= self.history.entries.len().saturating_sub(1) {
                self.history_index = None;
                self.input.set_content("");
            } else {
                let target = idx + 1;
                if let Some(entry) = self.history.entries.get(target).cloned() {
                    self.history_index = Some(target);
                    self.input.set_content(&entry);
                }
            }
        }
    }

    fn toggle_bookmark(&mut self) {
        let current = self.input.get_content();
        if current.is_empty() {
            return;
        }
        if !self.bookmarks.remove_first(&current) {
            self.bookmarks.add(&current);
        }
    }

    fn finish_history_add(&mut self) {
        self.history.add(&self.input.get_content());
    }

    pub fn finish_input(&self) -> String {
        self.input.get_content()
    }

    pub fn add_final_to_history(&mut self) {
        self.finish_history_add();
    }

    fn handle_list_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Esc => self.close_cmdlist(false),
            KeyCode::Enter => self.close_cmdlist(true),
            KeyCode::Up => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.move_by(-1);
                }
            }
            KeyCode::Down => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.move_by(1);
                }
            }
            KeyCode::PageUp => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.move_by(-5);
                }
            }
            KeyCode::PageDown => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.move_by(5);
                }
            }
            KeyCode::Backspace | KeyCode::Delete => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    view.delete_selected();
                }
            }
            KeyCode::Char(c) => {
                if let AppMode::CmdList(view) = &mut self.mode {
                    match c {
                        'k' => view.move_by(-1),
                        'j' => view.move_by(1),
                        'g' => view.move_by(-5),
                        'G' => view.move_by(5),
                        'u' => view.undo(),
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }

    fn handle_text_key(&mut self, key: KeyEvent) -> bool {
        let before = self.input.get_content();
        let handled = match key.code {
            KeyCode::Char(c) => {
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    match c {
                        'a' => self.input.home(),
                        'e' => self.input.end(),
                        'u' | 'x' => self.input.clear(),
                        'w' => self.input.delete_word(),
                        _ => self.input.insert_char(c),
                    }
                } else {
                    self.input.insert_char(c);
                }
                true
            }
            KeyCode::Backspace => {
                self.input.backspace();
                true
            }
            KeyCode::Delete => {
                self.input.delete();
                true
            }
            KeyCode::Left => {
                self.input.move_left();
                true
            }
            KeyCode::Right => {
                self.input.move_right();
                true
            }
            KeyCode::Up => {
                self.input.move_up();
                true
            }
            KeyCode::Down => {
                self.input.move_down();
                true
            }
            KeyCode::Home => {
                self.input.home();
                true
            }
            KeyCode::End => {
                self.input.end();
                true
            }
            KeyCode::Insert => {
                self.input.insert_newline();
                true
            }
            KeyCode::Enter if key.modifiers.contains(KeyModifiers::ALT) => {
                self.input.insert_newline();
                true
            }
            _ => false,
        };
        if handled {
            self.history_index = None;
            if self.input.get_content() != before {
                self.maybe_autoeval();
            }
        }
        handled
    }

    pub fn handle_key(&mut self, key: KeyEvent) {
        // Global mode switches.
        if key.code == KeyCode::F(1) {
            self.mode = if matches!(self.mode, AppMode::Help) {
                AppMode::Main
            } else {
                AppMode::Help
            };
            return;
        }
        if key.code == KeyCode::F(4) {
            if matches!(
                self.mode,
                AppMode::CmdList(CmdListView {
                    kind: ListKind::History,
                    ..
                })
            ) {
                self.mode = AppMode::Main;
            } else {
                self.open_cmdlist(ListKind::History);
            }
            return;
        }
        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('b') {
            if matches!(
                self.mode,
                AppMode::CmdList(CmdListView {
                    kind: ListKind::Bookmarks,
                    ..
                })
            ) {
                self.mode = AppMode::Main;
            } else {
                self.open_cmdlist(ListKind::Bookmarks);
            }
            return;
        }

        match self.mode {
            AppMode::Help => {
                self.mode = AppMode::Main;
            }
            AppMode::CmdList(_) => {
                self.handle_list_key(key);
            }
            AppMode::Main => {
                if let Some(chooser) = self.chooser.take() {
                    if let KeyCode::Char(c) = key.code {
                        if let Some(value) = chooser.options.get(&c).cloned() {
                            match chooser.kind {
                                ChooserKind::Snippet => {
                                    self.input.insert_snippet(&value);
                                }
                                ChooserKind::HelpViewer => {
                                    self.pending_external = Some(ExternalAction::Help(value));
                                }
                                ChooserKind::OutputViewer => {
                                    self.pending_external = Some(ExternalAction::Output(
                                        value,
                                        self.command_output.clone(),
                                    ));
                                }
                            }
                        }
                    }
                    return;
                }

                if key.code == KeyCode::Esc
                    || (key.modifiers.contains(KeyModifiers::CONTROL)
                        && matches!(key.code, KeyCode::Char('c') | KeyCode::Char('q')))
                {
                    self.should_quit = true;
                    return;
                }

                match key.code {
                    KeyCode::F(2) => {
                        self.autoeval = !self.autoeval;
                    }
                    KeyCode::F(3) => {
                        self.paranoid = !self.paranoid;
                    }
                    KeyCode::F(5) => {
                        self.open_help_chooser();
                    }
                    KeyCode::F(6) => {
                        self.chooser = Some(Chooser {
                            kind: ChooserKind::OutputViewer,
                            options: self.config.output_viewers.clone(),
                        });
                    }
                    KeyCode::F(7) => {
                        self.cache_at_pipe();
                    }
                    KeyCode::Enter if !key.modifiers.contains(KeyModifiers::ALT) => {
                        self.history_index = None;
                        self.history.add(&self.input.get_content());
                        self.start_evaluation();
                    }
                    KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.toggle_bookmark();
                    }
                    KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.history_previous();
                    }
                    KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.history_next();
                    }
                    KeyCode::Char('v') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.chooser = Some(Chooser {
                            kind: ChooserKind::Snippet,
                            options: self.config.snippets.clone(),
                        });
                    }
                    _ => {
                        self.handle_text_key(key);
                    }
                }
            }
        }
    }
}

pub fn run_external_action(
    action: &ExternalAction,
    terminal: &mut Terminal<CrosstermBackend<io::Stderr>>,
) -> io::Result<()> {
    execute!(io::stdout(), LeaveAlternateScreen)?;
    match action {
        ExternalAction::Help(command) => {
            let _ = Command::new("bash").arg("-c").arg(command).status()?;
        }
        ExternalAction::Output(program, output) => {
            let mut child = Command::new(program).stdin(Stdio::piped()).spawn()?;
            if let Some(mut stdin) = child.stdin.take() {
                stdin.write_all(output.as_bytes())?;
            }
            let _ = child.wait()?;
        }
    }
    execute!(io::stdout(), EnterAlternateScreen)?;
    terminal.clear()?;
    Ok(())
}
RS"}

{"command":"mkdir -p src/ui
cat > src/ui/mod.rs <<'RS'
use ratatui::{
    layout::{Constraint, Direction, Layout, Position, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span, Text},
    widgets::{Block, Borders, List, ListItem, Paragraph},
    Frame,
};
use unicode_width::UnicodeWidthChar;

use crate::ansi::ansi_to_text;
use crate::app::{App, AppMode, ChooserKind, ListKind, SPINNER_FRAMES};
use crate::highlight::highlight_lines;

const HELP_TEXT: &str = "F1         Show/hide help
F2         Toggle autoeval
F3         Toggle Paranoid history (fills up history in autoeval)
F4         Show/hide history
Ctrl+B     Show/hide bookmarks
F5         Open helpviewer
F6         Open outputviewer
F7         When the cursor is on a `|` symbol, cache the output of everything before that |
Ctrl+S     Save bookmark
Alt+Return Newline
Ctrl+U     Clear Command
Ctrl+P     Previous in history
Ctrl+N     Next in history
Ctrl+V     Insert snippet (press corresponding key to choose)

disable a line by starting it with a #
this will simply exclude the line from the executed command.

Config file is in
~/.config/pipr/pipr.toml";

fn active_title(title: &str) -> Line<'static> {
    Line::from(Span::styled(
        format!(" {} ", title),
        Style::default().fg(Color::Black).bg(Color::Cyan),
    ))
}

fn inactive_title(title: &str) -> Line<'static> {
    Line::from(Span::styled(
        format!(" {} ", title),
        Style::default().fg(Color::Cyan),
    ))
}

fn block(title: Line<'static>) -> Block<'static> {
    Block::default().borders(Borders::ALL).title(title)
}

fn truncate_line(line: &str, area_width: u16) -> String {
    let interior = (area_width as usize).saturating_sub(2);
    if interior >= 3 && line.len() > interior - 3 {
        let mut s = line.to_string();
        s.truncate(interior - 3);
        s.push_str("...");
        s
    } else {
        line.to_string()
    }
}

fn command_title(app: &App) -> String {
    let mut title = "Command".to_string();
    if app.is_bookmarked() {
        title.push_str(" [Bookmarked]");
    }
    if app.autoeval {
        title.push_str(" [Autoeval]");
    }
    if app.is_caching() {
        title.push_str(" [Caching]");
    }
    if app.autoeval && app.paranoid {
        title.push_str(" [Paranoid]");
    }
    title
}

fn output_title(app: &App) -> String {
    let mut title = "Output".to_string();
    if app.input.get_content() != app.last_evaluated_input {
        title.push_str(" [+]");
    }
    if app.is_evaluating {
        title.push(' ');
        title.push_str(SPINNER_FRAMES[app.spinner_idx % SPINNER_FRAMES.len()]);
    }
    title
}

fn draw_main(frame: &mut Frame, app: &mut App, area: Rect) {
    let cmd_height = (app.input.lines.len() as u16).saturating_add(2);
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(cmd_height), Constraint::Min(0)])
        .split(area);

    // Command box.
    let display_lines: Vec<String> = app
        .input
        .lines
        .iter()
        .map(|line| truncate_line(line, chunks[0].width))
        .collect();
    let text_lines: Vec<Line> = if app.config.highlighting_enabled {
        highlight_lines(&display_lines)
    } else {
        display_lines.into_iter().map(Line::from).collect()
    };
    let command_widget = Paragraph::new(Text::from(text_lines))
        .block(block(active_title(&command_title(app))));
    frame.render_widget(command_widget, chunks[0]);

    let cursor_prefix_width: u16 = app
        .input
        .lines
        .get(app.input.cursor_y)
        .map(|line| {
            line.chars()
                .take(app.input.cursor_x)
                .map(|c| UnicodeWidthChar::width(c).unwrap_or(1) as u16)
                .sum()
        })
        .unwrap_or(0);
    frame.set_cursor_position(Position {
        x: chunks[0].x + 1 + cursor_prefix_width,
        y: chunks[0].y + 1 + app.input.cursor_y as u16,
    });

    // Output and, on failure, stderr.
    if let Some(stderr) = &app.error_output {
        let out_chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
            .split(chunks[1]);
        let out_widget = Paragraph::new(ansi_to_text(&app.command_output))
            .block(block(inactive_title(&output_title(app))));
        frame.render_widget(out_widget, out_chunks[0]);
        let err_widget = Paragraph::new(ansi_to_text(stderr))
            .block(block(inactive_title("Stderr")));
        frame.render_widget(err_widget, out_chunks[1]);
    } else {
        let out_widget = Paragraph::new(ansi_to_text(&app.command_output))
            .block(block(inactive_title(&output_title(app))));
        frame.render_widget(out_widget, chunks[1]);
    }
}

pub fn draw(frame: &mut Frame, app: &mut App) {
    let size = frame.area();

    match &mut app.mode {
        AppMode::Help => {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Percentage(100)])
                .margin(1)
                .split(size);
            let help = Paragraph::new(HELP_TEXT).block(block(active_title("Help")));
            frame.render_widget(help, chunks[0]);
        }
        AppMode::CmdList(view) => {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
                .margin(1)
                .split(size);
            let title = match view.kind {
                ListKind::History => "History",
                ListKind::Bookmarks => "Bookmarks",
            };
            let items: Vec<ListItem> = view
                .entries
                .iter()
                .map(|entry| ListItem::new(entry.replace('\n', " ↵ ")))
                .collect();
            let list = List::new(items)
                .block(block(active_title(title)))
                .highlight_style(Style::default().add_modifier(Modifier::ITALIC))
                .highlight_symbol(">>");
            view.sync_state();
            // Extract the state temporarily to satisfy the borrow checker
            // while app is borrowed mutably below.
            let mut state = std::mem::take(&mut view.state);
            frame.render_stateful_widget(list, chunks[0], &mut state);
            // Put it back and learn any clamping the widget applied.
            if let AppMode::CmdList(view) = &mut app.mode {
                view.state = state;
                if let Some(sel) = view.state.selected() {
                    if !view.entries.is_empty() {
                        view.selected = Some(sel.min(view.entries.len() - 1));
                    }
                }
                let show_preview = view
                    .selected_entry()
                    .map(|entry| {
                        app.config.cmdlist_always_show_preview || entry.contains('\n')
                    })
                    .unwrap_or(false);
                if show_preview {
                    let text = view.selected_entry().unwrap_or("").to_string();
                    let preview = Paragraph::new(text)
                        .block(block(inactive_title("Preview")));
                    frame.render_widget(preview, chunks[1]);
                }
            }
        }
        AppMode::Main => {
            if let Some(chooser) = &app.chooser {
                let chunks = Layout::default()
                    .direction(Direction::Horizontal)
                    .constraints([Constraint::Percentage(40), Constraint::Percentage(60)])
                    .margin(1)
                    .split(size);
                let lines: Vec<Line> = chooser
                    .options
                    .iter()
                    .map(|(key, value)| {
                        let mut display = value.replace('\n', "");
                        if chooser.kind == ChooserKind::Snippet {
                            display = display.replace("||", "");
                        }
                        Line::from(format!("{}: {}", key, display))
                    })
                    .collect();
                let chooser_widget =
                    Paragraph::new(Text::from(lines)).block(block(inactive_title("Open in")));
                frame.render_widget(chooser_widget, chunks[0]);
                draw_main(frame, app, chunks[1]);
            } else {
                let chunks = Layout::default()
                    .direction(Direction::Vertical)
                    .constraints([Constraint::Percentage(100)])
                    .margin(1)
                    .split(size);
                draw_main(frame, app, chunks[0]);
            }
        }
    }

    let help_area = Rect {
        x: size.width.wrapping_sub(12),
        y: size.height.wrapping_sub(2),
        width: 10,
        height: 1,
    };
    frame.render_widget(Paragraph::new("Help: F1"), help_area);
}
RS"}

