pub fn draw(frame: &mut Frame, app: &mut App) {
    let size = frame.area();

    match &mut app.mode {
        AppMode::Help => {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Percentage(100)])
                .margin(1)
                .split(size);
            let help = Paragraph::new(HELP_TEXT).block(block(active_title("Help")));
            frame.render_widget(help, chunks[0]);
        }
        AppMode::CmdList(view) => {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
                .margin(1)
                .split(size);
            let title = match view.kind {
                ListKind::History => "History",
                ListKind::Bookmarks => "Bookmarks",
            };
            let items: Vec<ListItem> = view
                .entries
                .iter()
                .map(|entry| ListItem::new(entry.replace('\n', " ↵ ")))
                .collect();
            let list = List::new(items)
                .block(block(active_title(title)))
                .highlight_style(Style::default().add_modifier(Modifier::ITALIC))
                .highlight_symbol(">>");
