fn truncate_line(line: &str, area_width: u16) -> String {
    let interior = (area_width as usize).saturating_sub(2);
    if interior >= 3 && line.len() > interior - 3 {
        let mut s = line.to_string();
        s.truncate(interior - 3);
        s.push_str("...");
        s
    } else {
        line.to_string()
    }
