#[derive(Debug, Clone, Default)]
pub struct OptMatches {
    pub default: Option<String>,
    pub out_file: Option<String>,
    pub in_file: Option<String>,
    pub config_reference: bool,
    pub raw_mode: bool,
    pub no_isolation: bool,
    pub help: bool,
}

#[derive(Debug)]
pub enum OptError {
    Unrecognized(String),
    Missing(String),
    DoesNotTake(String),
    MoreThanOnce(String),
}

impl std::fmt::Display for OptError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            OptError::Unrecognized(name) => write!(f, "Unrecognized option: '{}'", name),
            OptError::Missing(name) => write!(f, "Argument to option '{}' missing", name),
            OptError::DoesNotTake(name) => {
                write!(f, "Option '{}' does not take an argument", name)
            }
            OptError::MoreThanOnce(name) => {
                write!(f, "Option '{}' given more than once", name)
            }
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct OptDef {
    short: Option<char>,
    long: &'static str,
    takes_arg: bool,
}

const OPTS: &[OptDef] = &[
    OptDef {
        short: Some('d'),
        long: "default",
        takes_arg: true,
    },
    OptDef {
        short: Some('o'),
        long: "out-file",
        takes_arg: true,
    },
    OptDef {
        short: None,
        long: "in-file",
        takes_arg: true,
    },
    OptDef {
        short: None,
        long: "config-reference",
        takes_arg: false,
    },
    OptDef {
        short: Some('r'),
        long: "raw-mode",
        takes_arg: false,
    },
    OptDef {
        short: None,
        long: "no-isolation",
        takes_arg: false,
    },
    OptDef {
        short: Some('h'),
        long: "help",
        takes_arg: false,
    },
];

pub fn usage(program: &str) -> String {
    format!(
        "Usage: {} [options]\n\nOptions:\n    -d, --default TEXT  text inserted into the textfield on startup\n    -o, --out-file FILE write final command to file\n        --in-file FILE  read initial command from file\n        --config-reference \n                        print out the default configuration file\n    -r, --raw-mode      keep linebreaks in finished command when closing\n        --no-isolation  disable isolation. This will run the commands directly\n                        on your system, without protection. Take care.\n    -h, --help          print this help menu\n",
        program
    )
}

fn record(
    seen: &mut Vec<&'static str>,
    matches: &mut OptMatches,
    def: OptDef,
    value: Option<String>,
) -> Result<(), OptError> {
    if seen.contains(&def.long) {
        return Err(OptError::MoreThanOnce(def.long.to_string()));
    }
    seen.push(def.long);
    match def.long {
        "default" => matches.default = value,
        "out-file" => matches.out_file = value,
        "in-file" => matches.in_file = value,
        "config-reference" => matches.config_reference = true,
        "raw-mode" => matches.raw_mode = true,
        "no-isolation" => matches.no_isolation = true,
        "help" => matches.help = true,
        _ => {}
    }
    Ok(())
}

pub fn parse(args: &[String]) -> Result<OptMatches, OptError> {
    let mut matches = OptMatches::default();
    let mut seen: Vec<&'static str> = Vec::new();
    let mut only_free = false;
    let mut i = 0;

    while i < args.len() {
        let arg = &args[i];
        i += 1;
        if only_free || arg == "-" || arg.is_empty() || !arg.starts_with('-') {
            continue;
        }
        if arg == "--" {
            only_free = true;
            continue;
        }
        if let Some(long_arg) = arg.strip_prefix("--") {
            let (name, inline_value) = match long_arg.find('=') {
                Some(pos) => (&long_arg[..pos], Some(long_arg[pos + 1..].to_string())),
                None => (long_arg, None),
            };
            let (def, display_name) = if let Some(def) = OPTS.iter().find(|o| o.long == name) {
                (*def, name.to_string())
            } else if name.chars().count() == 1 {
                let ch = name.chars().next().unwrap();
                match OPTS.iter().find(|o| o.short == Some(ch)) {
                    Some(def) => (*def, name.to_string()),
                    None => return Err(OptError::Unrecognized(name.to_string())),
                }
            } else {
                return Err(OptError::Unrecognized(name.to_string()));
            };

            if def.takes_arg {
                let value = if let Some(v) = inline_value {
                    v
                } else if i < args.len() {
                    let v = args[i].clone();
                    i += 1;
                    v
                } else {
                    return Err(OptError::Missing(display_name));
                };
                record(&mut seen, &mut matches, def, Some(value))?;
            } else {
                if inline_value.is_some() {
                    return Err(OptError::DoesNotTake(display_name));
                }
                record(&mut seen, &mut matches, def, None)?;
            }
        } else {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let ch = chars[j];
                let def = match OPTS.iter().find(|o| o.short == Some(ch)) {
                    Some(def) => *def,
                    None => return Err(OptError::Unrecognized(ch.to_string())),
                };
                if def.takes_arg {
                    let value = if j + 1 < chars.len() {
                        chars[j + 1..].iter().collect::<String>()
                    } else if i < args.len() {
                        let v = args[i].clone();
                        i += 1;
                        v
                    } else {
                        return Err(OptError::Missing(ch.to_string()));
                    };
                    record(&mut seen, &mut matches, def, Some(value))?;
                    break;
                } else {
                    record(&mut seen, &mut matches, def, None)?;
                }
                j += 1;
            }
        }
    }
    Ok(matches)
}
RS"}

