{"command":"cat > src/main.rs <<'RS'
mod ansi;
mod app;
mod cli;
mod commandlist;
mod executor;
mod highlight;
mod pipr_config;
mod textfield;
mod ui;

use std::env;
use std::fs;
use std::io::{self, Write};
use std::os::unix::fs::PermissionsExt;
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use anyhow::Result;
use crossterm::{
    event::{self, Event},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{backend::CrosstermBackend, Terminal};

use app::App;
use commandlist::CommandList;
use pipr_config::PiprConfig;

fn bwrap_available() -> bool {
    let Some(paths) = env::var_os("PATH") else {
        return false;
    };
    for dir in env::split_paths(&paths) {
        let candidate = dir.join("bwrap");
        if let Ok(metadata) = fs::metadata(&candidate) {
            if metadata.is_file() && metadata.permissions().mode() & 0o111 != 0 {
                return true;
            }
        }
    }
    false
}

fn set_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        let _ = disable_raw_mode();
        let _ = execute!(io::stdout(), LeaveAlternateScreen);
        let _ = execute!(io::stderr(), LeaveAlternateScreen);
        eprintln!("{}", info);
        std::process::exit(1);
    }));
}

fn run_finish_hook(hook: &str, finished: &str) -> Result<()> {
    let mut parts = hook.split(' ');
    let program = parts.next().unwrap_or("");
    let mut child = Command::new(program)
        .args(parts)
        .stdin(Stdio::piped())
        .spawn()?;
    if let Some(mut stdin) = child.stdin.take() {
        let _ = stdin.write_all(finished.as_bytes());
    }
    let _ = child.wait()?;
    Ok(())
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    let program = args.first().cloned().unwrap_or_default();
    let matches = match cli::parse(&args[1..]) {
        Ok(matches) => matches,
        Err(e) => {
            eprintln!("{}: {}", program, e);
            std::process::exit(1);
        }
    };

    if matches.help {
        print!("{}", cli::usage(&program));
        return Ok(());
    }
    if matches.config_reference {
        println!("{}", pipr_config::DEFAULT_CONFIG);
        return Ok(());
    }

    let home = env::var("HOME").expect("$HOME not set");
    let config_root = match env::var("XDG_CONFIG_HOME") {
        Ok(xdg) => PathBuf::from(xdg),
        Err(_) => PathBuf::from(&home).join(".config"),
    };
    let config_dir = config_root.join("pipr");
    let config_path = config_dir.join("pipr.toml");
    let config = PiprConfig::load(&config_path).unwrap();

    let isolation = !matches.no_isolation;
    if isolation && !bwrap_available() {
        println!(
            "bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode"
        );
        std::process::exit(1);
    }

    let history = CommandList::load(
        config_dir.join("history"),
        Some(config.history_size),
    );
    let bookmarks = CommandList::load(config_dir.join("bookmarks"), None);

    let initial = if let Some(in_file) = &matches.in_file {
        fs::read_to_string(in_file)?
    } else if let Some(default) = &matches.default {
        default.clone()
    } else {
        String::new()
    };

    let mut app = App::new(config.clone(), history, bookmarks, &initial, isolation);

    let mut stderr = io::stderr();
    execute!(stderr, EnterAlternateScreen)?;
    enable_raw_mode()?;
    set_panic_hook();
    let backend = CrosstermBackend::new(stderr);
    let mut terminal = Terminal::new(backend)?;

    let mut last_tick = Instant::now();
    loop {
        app.validate_cache();
        terminal.draw(|frame| ui::draw(frame, &mut app))?;

        let timeout = Duration::from_millis(100)
            .checked_sub(last_tick.elapsed())
            .unwrap_or(Duration::ZERO);
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                app.handle_key(key);
                if let Some(action) = app.pending_external.take() {
                    let _ = app::run_external_action(&action, &mut terminal);
                }
                if app.should_quit {
                    break;
                }
            }
        }
        if last_tick.elapsed() >= Duration::from_millis(100) {
            app.on_tick();
            last_tick = Instant::now();
        }
        app.poll_evaluations();
    }

    app.add_final_to_history();
    let raw_final = app.finish_input();

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;

    let finished = if matches.raw_mode {
        raw_final
    } else {
        raw_final.replace('\n', " ")
    };

    if let Some(hook) = &config.finish_hook {
        run_finish_hook(hook, &finished)?;
    }
    println!("{}", finished);
    if let Some(out_file) = &matches.out_file {
        fs::write(out_file, &finished)?;
    }
    Ok(())
}
RS"}

