use ratatui::{backend::CrosstermBackend, Terminal, widgets::{Paragraph,Widget,Block,Borders}, text::Line, buffer::Buffer, layout::Rect};
use crossterm::{execute, terminal::{enable_raw_mode,disable_raw_mode,EnterAlternateScreen,LeaveAlternateScreen}, event};
use std::io;
struct W;
impl Widget for W {
 fn render(self, area: Rect, buf: &mut Buffer) {
   buf.cell_mut((area.x, area.y)).unwrap().set_symbol("a\t");
   buf.cell_mut((area.x+1, area.y)).unwrap().set_symbol("b");
   buf.cell_mut((area.x, area.y+1)).unwrap().set_symbol("c\r");
   buf.cell_mut((area.x+1, area.y+1)).unwrap().set_symbol("d");
   buf.cell_mut((area.x, area.y+2)).unwrap().set_symbol("e\x08");
   buf.cell_mut((area.x+1, area.y+2)).unwrap().set_symbol("f");
 }
}
fn main()->io::Result<()>{
 let mut stderr=io::stderr(); execute!(stderr,EnterAlternateScreen)?; enable_raw_mode()?;
 let backend=CrosstermBackend::new(stderr); let mut term=Terminal::new(backend)?;
 term.draw(|f|{
   let a=f.area();
   f.render_widget(W, Rect{x:a.x+2,y:a.y+2,width:10,height:4});
   f.render_widget(Paragraph::new(Line::from("x\ty")), Rect{x:a.x+2,y:a.y+7,width:20,height:1});
 })?;
 let _=event::read();
 disable_raw_mode()?; execute!(term.backend_mut(),LeaveAlternateScreen)?; Ok(())
}
