header="""use anyhow::{anyhow, Result};
use std::collections::HashMap;
use std::fs;
use std::path::{Component, Path, PathBuf};

"""
impl_text='''impl PiprConfig {
    pub fn load(path: &Path) -> Self {
        let directory_containing_a_config_file = match path.parent() {
            Some(parent) => parent.to_path_buf(),
            None => PathBuf::new(),
        };

        // Creating the directory is harmless if it already exists.
        fs::create_dir_all(directory_containing_a_config_file.as_path()).unwrap();

        create_default_config_file(path);

        // Parsing and interpreting the file is fatal on error:
        // there is no useful fallback configuration to continue
        // with if the user's file cannot be understood.
        let conf = Self::load_from_file(path);
        conf.unwrap()
    }

    fn load_from_file(path: &Path) -> Result<Self> {
        if !path.is_file() {
            return Err(anyhow!("configuration file {:?} not found", path));
        }
        let content = fs::read_to_string(path)?;
        let table: toml::Table = toml::from_str(&content).map_err(|e| {
            anyhow!("{} in {}", e, relative_display(path))
        })?;

        // The shell used for evaluations is the only structured value
        // which is extracted here rather than in the literal below.
        let eval_environment = match table.get("eval_environment") { Some(toml::Value::Array(items)) => items.iter().filter_map(scalar_to_string).collect(), _ => vec!["bash".to_string(), "-c".to_string()], };

        Ok(Self {
            finish_hook: table.get("finish_hook").and_then(scalar_to_string),
            paranoid_history_mode_default: get_bool(
                &table,
                "paranoid_history_mode_default",
                false,
            ),
            autoeval_mode_default: get_bool(&table, "autoeval_mode_default", false),
            history_size: get_int(&table, "history_size", 500) as usize,
            cmdlist_always_show_preview: get_bool(
                &table,
                "cmdlist_always_show_preview",
                false,
            ),
            cmd_timeout_millis: get_int(&table, "cmd_timeout_millis", 2000) as u64,
            highlighting_enabled: get_bool(&table, "highlighting_enabled", true),
            eval_environment,
            snippets: get_map(&table, "snippets").unwrap_or_default(),
            help_viewers: get_map(&table, "help_viewers").unwrap_or_else(default_help_viewers),
            output_viewers: get_map(&table, "output_viewers").unwrap_or_else(default_output_viewers),
        })
    }
}

fn create_default_config_file(path: &Path) {
    if path.exists() {
        return;
    }

    let default_contents = DEFAULT_CONFIG;
    fs::write(path, default_contents).unwrap();
}

