{"command":"cat > src/textfield.rs <<'RS'
#[derive(Debug, Clone)]
pub struct TextField {
    pub lines: Vec<String>,
    /// Byte offset into the current line. This is deliberately not
    /// adjusted to a character boundary by vertical movement.
    pub cursor_x: usize,
    pub cursor_y: usize,
}

impl Default for TextField {
    fn default() -> Self {
        Self {
            lines: vec![String::new()],
            cursor_x: 0,
            cursor_y: 0,
        }
    }
}

impl TextField {
    pub fn set_content(&mut self, content: &str) {
        self.lines = content.lines().map(|s| s.to_string()).collect();
        if self.lines.is_empty() {
            self.lines.push(String::new());
        }
        self.cursor_y = self.lines.len() - 1;
        self.cursor_x = self.lines[self.cursor_y].len();
    }

    pub fn get_content(&self) -> String {
        self.lines.join("\n")
    }

    fn current_line_len(&self) -> usize {
        self.lines[self.cursor_y].len()
    }

    pub fn insert_char(&mut self, c: char) {
        self.lines[self.cursor_y].insert(self.cursor_x, c);
        self.cursor_x += c.len_utf8();
    }

    pub fn insert_snippet(&mut self, snippet: &str) {
        let placeholder_pos = snippet.find("||");
        let cleansed = snippet.replace("||", "");
        self.lines[self.cursor_y].insert_str(self.cursor_x, &cleansed);
        self.cursor_x += placeholder_pos.unwrap_or_else(|| cleansed.len());
    }

    pub fn insert_newline(&mut self) {
        let after = self.lines[self.cursor_y][self.cursor_x..].to_string();
        self.lines[self.cursor_y].truncate(self.cursor_x);
        self.cursor_y += 1;
        self.cursor_x = 0;
        self.lines.insert(self.cursor_y, after);
    }

    pub fn backspace(&mut self) {
        if self.cursor_x > 0 {
            let prev = self.lines[self.cursor_y][..self.cursor_x]
                .char_indices()
                .last()
                .map(|(idx, _)| idx)
                .unwrap_or(0);
            self.lines[self.cursor_y].replace_range(prev..self.cursor_x, "");
            self.cursor_x = prev;
        } else if self.cursor_y > 0 {
            let current = self.lines.remove(self.cursor_y);
            self.cursor_y -= 1;
            self.cursor_x = self.current_line_len();
            self.lines[self.cursor_y].push_str(&current);
        }
    }

    pub fn delete(&mut self) {
        if self.cursor_x < self.current_line_len() {
            let next = self.lines[self.cursor_y][self.cursor_x..]
                .chars()
                .next()
                .map(|c| self.cursor_x + c.len_utf8())
                .unwrap_or_else(|| self.cursor_x);
            self.lines[self.cursor_y].replace_range(self.cursor_x..next, "");
        } else if self.cursor_y + 1 < self.lines.len() {
            let next = self.lines.remove(self.cursor_y + 1);
            self.lines[self.cursor_y].push_str(&next);
        }
    }

    pub fn move_left(&mut self) {
        if self.cursor_x > 0 {
            self.cursor_x = self.lines[self.cursor_y][..self.cursor_x]
                .char_indices()
                .last()
                .map(|(idx, _)| idx)
                .unwrap_or(0);
        } else if self.cursor_y > 0 {
            self.cursor_y -= 1;
            self.cursor_x = self.current_line_len();
        }
    }

    pub fn move_right(&mut self) {
        if self.cursor_x < self.current_line_len() {
            if let Some(c) = self.lines[self.cursor_y][self.cursor_x..].chars().next() {
                self.cursor_x += c.len_utf8();
            }
        } else if self.cursor_y + 1 < self.lines.len() {
            self.cursor_y += 1;
            self.cursor_x = 0;
        }
    }

    pub fn move_up(&mut self) {
        if self.cursor_y > 0 {
            self.cursor_y -= 1;
            self.cursor_x = self.cursor_x.min(self.current_line_len());
        }
    }

    pub fn move_down(&mut self) {
        if self.cursor_y + 1 < self.lines.len() {
            self.cursor_y += 1;
            self.cursor_x = self.cursor_x.min(self.current_line_len());
        }
    }

    pub fn home(&mut self) {
        self.cursor_x = 0;
    }

    pub fn end(&mut self) {
        self.cursor_x = self.current_line_len();
    }

    pub fn clear(&mut self) {
        self.lines = vec![String::new()];
        self.cursor_x = 0;
        self.cursor_y = 0;
    }

    pub fn delete_word(&mut self) {
        let separators = [' ', '/', '-', '_', ':', '\\'];
        if self.cursor_x == 0 {
            if let Some(first) = self.lines[self.cursor_y].chars().next() {
                // This mirrors a boundary case of the utility being recreated.
                self.lines[self.cursor_y].replace_range(0..first.len_utf8(), "");
            }
            return;
        }
        let start = self.lines[self.cursor_y][..self.cursor_x]
            .rfind(|c: char| separators.contains(&c))
            .unwrap_or(0);
        self.lines[self.cursor_y].replace_range(start..self.cursor_x, "");
        self.cursor_x = start;
    }

    pub fn absolute_cursor_byte(&self) -> usize {
        let mut pos = 0;
        for (idx, line) in self.lines.iter().enumerate() {
            if idx == self.cursor_y {
                pos += self.cursor_x;
                break;
            }
            pos += line.len() + 1;
        }
        pos
    }
}
